/* VA Loan Q&A library — the questions veterans, agents and LOs ask, with in-depth answers and references.
   Refs: VA Pamphlet 26-7 (Lenders Handbook) chapters; 38 U.S.C. Chapter 37; 38 CFR Part 36; VA Circulars; va.gov. Verify dated figures. */
const VQ=(cat,q,a,ref)=>({cat,q,a,ref});
const VA_QA=[
// ---------- Eligibility ----------
VQ("Eligibility","Who is eligible for a VA home loan?","Veterans, active-duty service members, National Guard and Reserve members, and certain surviving spouses who meet minimum service requirements and have a discharge other than dishonorable. Eligibility is proven with a Certificate of Eligibility (COE). Service requirements differ by era: 90 continuous days during wartime, 181 days during peacetime, 24 continuous months for enlisted after 9/7/1980 (officers after 10/16/1981), or 6 years in the Guard/Reserves (or 90 days active under Title 10, 30 of them consecutive, or qualifying Title 32 service).","38 U.S.C. §3702; VA Pamphlet 26-7 Ch.2 §1–2"),
VQ("Eligibility","Do I need to have been deployed or seen combat to qualify?","No. Eligibility is based on length and character of service, not combat. A veteran who served stateside for the minimum period with an honorable discharge is fully eligible.","26-7 Ch.2 §1"),
VQ("Eligibility","I was discharged early. Am I still eligible?","Possibly. Early discharges for a service-connected disability, hardship, reduction in force, certain medical conditions, or 'for the convenience of the government' after serving at least 20 continuous months of a 2-year enlistment can preserve eligibility. VA reviews the DD-214 narrative reason and separation code.","26-7 Ch.2 §1.b; 38 U.S.C. §3702(a)(2)"),
VQ("Eligibility","What if my discharge was 'Other Than Honorable' (OTH)?","An OTH discharge is not automatically disqualifying. You can request a Character of Service determination from VA (VA Form 26-1880 with a statement); VA decides whether the service is considered 'other than dishonorable' for benefit purposes. A dishonorable discharge or bad-conduct discharge from a general court-martial disqualifies.","26-7 Ch.2 §1; 38 CFR 3.12"),
VQ("Eligibility","Are National Guard members eligible without ever being federalized?","Yes, with 6 years of honorable service in the Selected Reserve (or 90 days of Title 32 service with at least 30 consecutive days, under the 2021 expansion). Members with fewer than 6 years may still qualify if discharged for a service-connected disability.","38 U.S.C. §3702(a)(2)(E); PL 116-315 §2001"),
VQ("Eligibility","Can a surviving spouse use the VA loan?","Yes, if the veteran died in service or from a service-connected disability, is MIA/POW, or was totally disabled and died from any cause (with rating duration requirements). The spouse must generally be unremarried, or remarried after age 57 and on/after 12/16/2003. Apply with VA Form 26-1817.","38 U.S.C. §3701(b); 26-7 Ch.2 §4"),
VQ("Eligibility","Can I use a VA loan more than once?","Yes. Entitlement can be restored after the prior loan is paid off and the property sold (or once in a lifetime without selling), and second-tier (bonus) entitlement often allows a second VA loan while keeping the first.","26-7 Ch.2 §9; 38 U.S.C. §3702(b)"),
VQ("Eligibility","Can two veterans buy together and combine entitlement?","Yes. Married veterans can each use entitlement; unmarried veterans can obtain a joint loan with each using entitlement for their share (prior VA approval is required for unmarried co-borrower joint loans).","26-7 Ch.7"),
VQ("Eligibility","Can a non-veteran spouse be on the loan?","Yes. A spouse can be a co-borrower with no down payment requirement; the spouse's income and credit are used. A non-spouse non-veteran co-borrower requires a joint loan with a down payment on the non-veteran's portion.","26-7 Ch.7 §2–3"),
VQ("Eligibility","Can I use a VA loan while still on active duty?","Yes. Active-duty members qualify after 90 continuous days of service. Income continuance (ETS/EAS date) must extend at least 12 months past closing or be supported by re-enlistment intent or civilian job evidence.","26-7 Ch.2 §1; Ch.4 §2.e"),
VQ("Eligibility","Are reservists on Title 10 orders eligible with less than 6 years?","Yes, after 90 continuous days of active service under Title 10 (or 181 in peacetime), the same as active duty.","26-7 Ch.2 §1"),
VQ("Eligibility","Does a Purple Heart change anything?","Active-duty Purple Heart recipients are exempt from the funding fee; eligibility itself follows normal service rules.","38 U.S.C. §3729(b)(2)(F)"),
VQ("Eligibility","Can I get a VA loan if I'm a Public Health Service or NOAA officer?","Yes. Commissioned officers of the PHS and NOAA are considered service members for VA home loan eligibility.","38 U.S.C. §101(21); 26-7 Ch.2"),
VQ("Eligibility","Do cadets and midshipmen qualify?","Service academy cadets/midshipmen are generally not eligible until they complete qualifying active service after graduation.","26-7 Ch.2 §1"),
VQ("Eligibility","Can I use the VA loan if I'm not a U.S. citizen?","Yes. Eligibility is about service, not citizenship. Non-citizen veterans with qualifying service are eligible; lenders verify legal residency for lending purposes.","26-7 Ch.2; Ch.4 §1"),
VQ("Eligibility","Does a VA home loan require me to be a first-time buyer?","No. There is no first-time-buyer requirement and the benefit can be reused for life.","26-7 Ch.2"),
VQ("Eligibility","Can I buy a home for my parents or child with my VA loan?","No. The veteran (or spouse) must occupy the home as a primary residence. Exceptions exist for a dependent child when the veteran is deployed, with the attorney-in-fact certifying occupancy.","26-7 Ch.3 §5"),
VQ("Eligibility","Is there an age limit for VA loans?","No minimum or maximum age beyond legal contract capacity; age cannot be used as a credit factor (ECOA).","ECOA Reg B; 26-7 Ch.4"),
VQ("Eligibility","Can a veteran with a prior VA foreclosure get another VA loan?","Yes, after 2 years typically, but entitlement used on the foreclosed loan remains tied up until VA's claim is repaid; remaining entitlement may still support a loan, and CAIVRS must be clear or the debt resolved.","26-7 Ch.2 §9; Ch.4 §7"),
VQ("Eligibility","Does bankruptcy affect VA eligibility?","Eligibility is unaffected; credit underwriting applies waiting periods (BK7: 2 years, 1–2 with extenuating circumstances; BK13: 12 months of payments with trustee approval).","26-7 Ch.4 §7.e"),
// ---------- COE ----------
VQ("COE","What is a Certificate of Eligibility and how do I get one?","The COE proves to the lender that you have VA entitlement and shows how much. Lenders can usually pull it in seconds via WebLGY (ACE). Veterans can also request it at va.gov (eBenefits) or by mail with VA Form 26-1880 and a DD-214 or statement of service.","26-7 Ch.2 §3"),
VQ("COE","What documents do I need for the COE?","Veterans: DD-214 (member 4 copy). Active duty: statement of service signed by the commander/personnel office with name, SSN, DOB, entry date, lost time, and the unit. Guard/Reserve: NGB-22/23 or points statement; current members a statement of service. Surviving spouses: VA Form 26-1817 and the veteran's DD-214/death evidence.","26-7 Ch.2 §3"),
VQ("COE","My COE shows 'entitlement used' from a loan I already paid off. What do I do?","Request restoration with VA Form 26-1880 and the payoff/HUD-1 evidence; if the property was sold and the loan paid in full, VA restores the entitlement. One-time restoration without selling is available if the loan is paid off.","26-7 Ch.2 §9"),
VQ("COE","What does the 'basic entitlement $36,000' on my COE mean?","It is the historical base guaranty amount. With full entitlement, VA guarantees 25% of the loan with no loan limit; the $36,000 figure matters only for computing partial entitlement after prior use.","26-7 Ch.2 §5; 38 U.S.C. §3703"),
VQ("COE","How is remaining entitlement calculated?","Maximum guaranty = 25% × the county conforming loan limit (2026 baseline $832,750 → $208,187). Subtract the entitlement charged on an existing VA loan. The remainder × 4 = the maximum loan with $0 down; above that, a 25% down payment on the excess.","26-7 Ch.3 §4; Circular 26-19-30"),
VQ("COE","Why does my COE list a funding-fee exemption status?","WebLGY checks VA compensation records; if you receive disability compensation (or are eligible to), the COE shows 'exempt' and the lender does not charge the fee. If it says 'non-exempt' but you have a rating, provide the award letter or request a VA determination (26-8937).","26-7 Ch.8 §8"),
VQ("COE","Can my lender get the COE if VA has no record of my service?","If ACE cannot find records, the lender submits the DD-214 through WebLGY or you mail VA Form 26-1880 to the Regional Loan Center; it can take 1–3 weeks.","26-7 Ch.2 §3"),
VQ("COE","My COE says 'This veteran's basic entitlement is $0.' Is that final?","It means all basic entitlement is in use; check for bonus (second-tier) entitlement and whether the prior loan can be restored. Many veterans with $0 basic still have usable second-tier entitlement in high-cost counties.","26-7 Ch.3 §4"),
VQ("COE","Does a COE expire?","No, but it reflects a point-in-time entitlement picture; lenders typically pull a fresh one at application and again before closing.","26-7 Ch.2 §3"),
VQ("COE","What is a 'substitution of entitlement' on the COE?","When a veteran buyer assumes another veteran's VA loan and substitutes their own entitlement, the seller's entitlement is restored and the buyer's COE shows the assumed loan.","26-7 Ch.5 §4"),
// ---------- Entitlement & limits ----------
VQ("Entitlement","Is there a maximum VA loan amount?","With full entitlement there is no VA loan limit; lenders set their own caps (commonly $1.5M–$3M+). With partial entitlement, county limits apply to the guaranty calculation and a down payment may be required above the computed ceiling.","Blue Water Navy Act 2019; Circular 26-19-30; 26-7 Ch.3"),
VQ("Entitlement","What are 'second-tier' or 'bonus' entitlement and how do they work?","Beyond the $36,000 basic entitlement, VA provides additional entitlement so that total guaranty reaches 25% of the county limit. A veteran with an existing VA loan can use the remaining portion to buy another primary home with $0 down up to (remaining × 4).","26-7 Ch.3 §4"),
VQ("Entitlement","Can I have two VA loans at the same time?","Yes, when remaining entitlement supports the new loan and the new home will be your primary residence (e.g., PCS). The old home can be kept as a rental.","26-7 Ch.3 §4; Ch.3 §5"),
VQ("Entitlement","How do I restore entitlement after selling my home?","Submit VA Form 26-1880 with evidence the loan was paid in full and the property disposed of; VA updates the COE. Lenders often do this through WebLGY.","26-7 Ch.2 §9"),
VQ("Entitlement","What is the one-time restoration?","Once in a lifetime, a veteran who has paid off a VA loan but still owns the property may have entitlement restored without selling. All further restorations require sale of the property.","38 U.S.C. §3702(b)(4); 26-7 Ch.2 §9.c"),
VQ("Entitlement","If I short-sold a VA home and VA paid a claim, can I use the benefit again?","Yes, but the entitlement used on that loan stays unavailable until the claim is repaid; remaining entitlement can be used, and the loss may be subject to a VA debt (CAIVRS).","26-7 Ch.2 §9; Ch.4 §7"),
VQ("Entitlement","Does the county loan limit still matter after the Blue Water Navy Act?","Only for veterans with partial entitlement; it sets the 25% guaranty maximum used to compute the $0-down ceiling and any down payment.","Circular 26-19-30"),
VQ("Entitlement","How does a down payment affect the guaranty on partial entitlement?","The guaranty must equal 25% of the loan. Remaining entitlement plus the veteran's down payment (or equity) together must reach 25% of the purchase price/loan amount.","26-7 Ch.3 §4"),
VQ("Entitlement","Can I use entitlement for a loan on a property outside the U.S.?","No. Properties must be in the United States, its territories or possessions.","26-7 Ch.3 §1"),
VQ("Entitlement","Will using VA now hurt my ability to use it later for a bigger home?","Not permanently; entitlement is restored on payoff and sale, and second-tier entitlement often allows a second purchase before then.","26-7 Ch.2 §9"),
// ---------- Funding fee ----------
VQ("Funding fee","What is the VA funding fee and how much is it?","A one-time fee paid to VA that funds the program in lieu of monthly MI. Purchase/construction: 2.15% first use with <5% down, 3.3% subsequent use; 1.5% with 5–9.99% down; 1.25% with 10%+ down. Cash-out refinance: 2.15%/3.3%. IRRRL: 0.5%. Assumptions: 0.5%. Rates set by statute through 2031 (Circular 26-23-06).","38 U.S.C. §3729; Circular 26-23-06"),
VQ("Funding fee","Who is exempt from the funding fee?","Veterans receiving VA disability compensation (or eligible but receiving retirement pay instead), veterans rated eligible for compensation from a pre-discharge exam, surviving spouses receiving DIC, and active-duty Purple Heart recipients.","38 U.S.C. §3729(c)"),
VQ("Funding fee","Can the funding fee be financed?","Yes. It can be added to the loan amount even above 100% LTV on a purchase; on cash-out refinances the total including the fee cannot exceed 100% of value.","26-7 Ch.8 §8; 38 CFR 36.4306"),
VQ("Funding fee","Can the seller pay my funding fee?","Yes. The funding fee is a 'concession' that counts toward the 4% seller concession cap.","26-7 Ch.8 §5"),
VQ("Funding fee","I got a disability rating after closing. Can I get the fee refunded?","If your claim was pending before closing and later granted with an effective date before closing, VA refunds the fee (lender processes through VA; refunds go to you or to principal if financed). File with the lender/RLC with the award letter.","26-7 Ch.8 §8.e; Circular 26-19-31"),
VQ("Funding fee","Is the funding fee tax-deductible?","Historically VA funding fees were deductible as mortgage insurance premiums when Congress extended that provision; the deduction has lapsed and been revived several times. Check the current tax year with a CPA.","IRS Pub 936 (current year)"),
VQ("Funding fee","Does a down payment lower the fee?","Yes: 5% down reduces the first-use fee to 1.5%; 10% down to 1.25% (same for subsequent use).","38 U.S.C. §3729(b)"),
VQ("Funding fee","Is the funding fee charged on an assumption?","Yes, 0.5% of the balance, paid by the assumer unless exempt; it cannot be financed.","38 U.S.C. §3729(b)(2)(G)"),
VQ("Funding fee","Which 'use' counts as first use?","First use means no prior VA-guaranteed loan has been obtained (except the fee for IRRRLs/assumptions). If prior use was with a down payment of 5% or more, the subsequent fee tiers still apply.","26-7 Ch.8 §8"),
VQ("Funding fee","Can the lender pay the funding fee through pricing?","Yes, as a lender credit at a higher rate; it is not a seller concession.","26-7 Ch.8 §3"),
// ---------- Credit ----------
VQ("Credit","What credit score do I need for a VA loan?","VA sets no minimum score. Lenders apply overlays—commonly 620, some 580, a few 500–560 with manual underwriting and strong compensating factors. The key VA factors are 12 months of satisfactory housing payment history and overall pattern.","26-7 Ch.4 §7"),
VQ("Credit","Can I get a VA loan with no credit score?","Yes. Lenders can use non-traditional credit (12 months of rent, utilities, insurance, phone) on a manual underwrite.","26-7 Ch.4 §7.c"),
VQ("Credit","How do collections affect VA approval?","VA does not require collections to be paid; the underwriter weighs them in the overall credit picture. Medical collections are disregarded. Lenders may require explanations or payment plans; judgments must be paid or under a documented plan.","26-7 Ch.4 §7"),
VQ("Credit","How long after a Chapter 7 bankruptcy can I get a VA loan?","Two years after discharge is generally acceptable; between 1 and 2 years may be approved if the bankruptcy was caused by circumstances beyond the borrower's control and credit has been re-established.","26-7 Ch.4 §7.e"),
VQ("Credit","Can I buy while in a Chapter 13?","Yes, after 12 months of on-time plan payments with trustee approval and satisfactory performance.","26-7 Ch.4 §7.e"),
VQ("Credit","How long after a foreclosure?","Generally 2 years; 1–2 years with extenuating circumstances. If the foreclosed loan was a VA loan, entitlement used remains unavailable until VA's loss is repaid.","26-7 Ch.4 §7.f"),
VQ("Credit","Do late payments disqualify me?","Not automatically. Isolated lates with explanations are weighed against the overall pattern; recent mortgage/rent lates are the most serious. Lenders typically require 0×30 housing in the last 12 months.","26-7 Ch.4 §7"),
VQ("Credit","Does VA require a minimum number of tradelines?","No. The underwriter evaluates the credit history as a whole; thin files can use alternative credit.","26-7 Ch.4 §7"),
VQ("Credit","Will a credit freeze or fraud alert stop my application?","You must lift freezes for all three bureaus so the lender can pull a tri-merge; fraud alerts require the lender to verify your identity by phone.","FCRA §605A"),
VQ("Credit","How does a co-signed loan count?","It counts in your DTI unless you document 12 months of payments made by the other party.","26-7 Ch.4 §5"),
VQ("Credit","Are deferred student loans counted?","If deferment extends more than 12 months beyond closing, the payment can be excluded; otherwise the lender uses the documented payment or 5% of the balance ÷ 12.","Circular 26-17-02; 26-7 Ch.4 §5"),
VQ("Credit","Does VA care about my spouse's credit if they're not on the loan?","In community-property states (CA, NV, AZ, TX, WA, ID, LA, NM, WI) the non-borrowing spouse's debts are counted (not their income or score); elsewhere they are not.","26-7 Ch.4 §2 & §5"),
VQ("Credit","Does CAIVRS matter?","Yes. A CAIVRS hit for a prior federal debt in default (VA, FHA, student loans) must be resolved or in a repayment plan before closing.","26-7 Ch.4 §7.h"),
VQ("Credit","Do disputed accounts cause problems?","Active disputes can trigger a refer in AUS; if the account is accurate, remove the dispute remark; if not, resolve it before application.","26-7 Ch.4; AUS guidance"),
VQ("Credit","How does a rapid rescore work?","Your lender submits creditor proof of a balance/status change to the bureaus through the credit vendor; scores update in 3–5 business days. Useful to move pricing tiers before locking.","Industry practice; FCRA"),
VQ("Credit","Can I qualify with a recent short sale?","Treated like a foreclosure: typically 2 years, less with extenuating circumstances; VA short sale may create a VA debt.","26-7 Ch.4 §7"),
VQ("Credit","Does an IRS payment plan block a VA loan?","No, if the plan is current; the monthly payment is included in debts. Tax liens generally must be paid or subordinated.","26-7 Ch.4 §5"),
VQ("Credit","What is a manual underwrite and when does VA require it?","When AUS returns Refer, or for certain circumstances (e.g., no score), a human underwriter reviews using VA's residual-income-first standards and compensating factors on VA Form 26-6393.","26-7 Ch.4 §10"),
VQ("Credit","Can authorized-user accounts help?","They can add history, but underwriters may discount accounts you don't pay; use with a documented history.","26-7 Ch.4 §7"),
VQ("Credit","Do medical collections count?","VA instructs lenders to disregard medical collections when evaluating credit, though they may still appear on the report.","26-7 Ch.4 §7"),
// ---------- Income / DTI / residual ----------
VQ("Income & residual","What is residual income?","The money left each month after taxes, debts, the proposed housing payment and estimated maintenance/utilities (14¢ per sq ft). VA sets minimums by region and family size; it is VA's primary affordability measure.","26-7 Ch.4 §9"),
VQ("Income & residual","What are the residual income requirements?","For loans over $80,000: Northeast $450/755/909/1,025/1,062 (family of 1–5), Midwest/South $441/738/889/1,003/1,039, West $491/823/990/1,117/1,158; add $80 per member over 5 (up to 7). Under $80,000 loan amounts have lower tables.","26-7 Ch.4 §9 tables"),
VQ("Income & residual","Is there a maximum DTI for VA loans?","No hard cap. 41% is a guideline; above it the lender must document residual income at least 120% of the table or other compensating factors. Approvals at 50–60% occur with strong residual.","26-7 Ch.4 §10"),
VQ("Income & residual","What counts as income?","Base pay, BAH, BAS, clothing allowance, special pays with continuance, overtime/bonus with 2-year history, self-employment (2 years), retirement/disability, rental (75% with lease), child support/alimony (if received reliably), etc. Non-taxable income can be grossed up (typically 25%).","26-7 Ch.4 §2"),
VQ("Income & residual","Does BAH count as income?","Yes. BAH and BAS are stable, verifiable allowances and count in full; being non-taxable they can be grossed up for ratio purposes (some lenders do not gross up BAH for residual).","26-7 Ch.4 §2.e"),
VQ("Income & residual","How is active-duty income verified?","With the two most recent Leave and Earnings Statements (LES), and evidence of continuance: the ETS/EAS date must be at least 12 months past closing or the member must show intent to re-enlist, a civilian job offer, or other evidence.","26-7 Ch.4 §2.e"),
VQ("Income & residual","My ETS is in 8 months. Can I still buy?","Yes, with a signed statement of intent to re-enlist and a commander's statement that re-enlistment is likely, or a valid civilian offer, or documented retirement income beginning on separation.","26-7 Ch.4 §2.e"),
VQ("Income & residual","Do I need two years on the job?","Generally 12 months of continuous employment or a 2-year history is expected; shorter periods are acceptable with related training or military experience in the same field.","26-7 Ch.4 §2"),
VQ("Income & residual","How is self-employment income calculated?","Two years of tax returns (business and personal); net income plus add-backs (depreciation, depletion, business use of home); declining income uses the lower year; a YTD P&L and business statements support stability.","26-7 Ch.4 §2.g"),
VQ("Income & residual","Can VA disability compensation be used as income?","Yes, and it is grossed up because it is non-taxable. Provide the award letter.","26-7 Ch.4 §2"),
VQ("Income & residual","Does child support I receive count?","Yes, if it is likely to continue (court order and history of receipt); it can be grossed up since it is non-taxable.","26-7 Ch.4 §2"),
VQ("Income & residual","What is the 5% military-facility reduction?","Active-duty, retired service members and some disabled veterans with access to commissary/exchange and medical facilities near the property may reduce the required residual income by 5%.","26-7 Ch.4 §9"),
VQ("Income & residual","How are family size and dependents counted for residual?","All household members including children and dependents, and a non-purchasing spouse. Court-ordered support obligations are debts.","26-7 Ch.4 §9"),
VQ("Income & residual","What debts are excluded from DTI?","Installment debts with fewer than 10 payments remaining (if not significant), co-signed debts paid by others for 12 months, deferred student loans beyond 12 months, and debts paid by a business with 12 months proof.","26-7 Ch.4 §5"),
VQ("Income & residual","Can rental income from the home I'm leaving count?","Yes: 75% of the lease amount typically, with the lease and deposit documented; VA does not require landlord experience for the departing residence on many lenders, but check overlays.","26-7 Ch.4 §2.n"),
VQ("Income & residual","Can rental income from the home I'm buying (2–4 units) count?","Yes, 75% of the appraiser's market rent or leases, provided you occupy one unit; some lenders require landlord experience or reserves.","26-7 Ch.4 §2.n"),
VQ("Income & residual","Are overtime and bonus income allowed?","With a 2-year history (12 months in some cases) and likelihood of continuance; declining trends are used conservatively.","26-7 Ch.4 §2"),
VQ("Income & residual","What is 'gross-up' and how much?","Non-taxable income (BAH/BAS, disability, SS, child support) can be increased for qualifying to reflect its after-tax value; VA lenders typically gross up 25%.","26-7 Ch.4 §2"),
VQ("Income & residual","How does VA treat alimony or child support I pay?","As a monthly obligation in DTI and residual.","26-7 Ch.4 §5"),
VQ("Income & residual","What compensating factors help a high-DTI VA file?","Excellent long-term credit, conservative use of credit, minimal consumer debt, long employment, significant liquid assets, sizable down payment, existing equity, little or no payment shock, military benefits, high residual income, low DTI, tax credits for childcare, tax benefits of homeownership.","26-7 Ch.4 §10"),
VQ("Income & residual","Can I qualify if I just started a civilian job after service?","Yes if the job is in the same field as your military occupation or training; otherwise a short history can be supported by an offer letter and probation terms.","26-7 Ch.4 §2"),
VQ("Income & residual","Does my spouse's income count if they are not on the loan?","No. Only borrowers' income counts, though a non-borrowing spouse's debts count in community-property states.","26-7 Ch.4 §2"),
VQ("Income & residual","What is the utilities/maintenance figure in residual?","Lenders estimate 14 cents per square foot of gross living area per month (higher in some lender policies); documented actual costs may be accepted.","26-7 Ch.4 §9"),
VQ("Income & residual","Can I use income from a job I'll start after closing?","Generally no unless the lender accepts an offer letter with a start within 60–90 days and reserves; VA requires the income to be reasonably likely and verifiable.","26-7 Ch.4 §2"),
// ---------- Assets / down payment ----------
VQ("Assets","Do I need a down payment?","No, with full entitlement and a purchase price supported by the appraisal. A down payment is required only when the price exceeds the VA value, on partial entitlement above the ceiling, or on joint loans with non-veterans.","26-7 Ch.3"),
VQ("Assets","Do I need cash reserves?","Not for a 1-unit home. For 2–4 units many lenders require 6 months PITI; rental-income use may require 6 months reserves per VA.","26-7 Ch.4 §2.n"),
VQ("Assets","Can I use gift funds?","Yes, from anyone with no interest in the transaction (seller, agent, builder excluded), with a gift letter and transfer evidence.","26-7 Ch.4 §8"),
VQ("Assets","What are 'large deposits' and why does the lender ask?","Deposits that are unusual relative to income must be sourced to confirm they are not undisclosed borrowed funds.","26-7 Ch.4 §8"),
VQ("Assets","Can I borrow my earnest money or closing costs?","Borrowed funds must be disclosed and the payment counted; VA permits secured borrowing (e.g., against an asset) in some cases, but unsecured personal loans for closing are generally not acceptable.","26-7 Ch.4 §8"),
VQ("Assets","Can I get cash back at closing on a VA purchase?","Only refunds of items you paid (EMD, appraisal) or seller credits that exceed costs cannot be cash; excess seller credits are lost or applied to points.","26-7 Ch.8 §5"),
VQ("Assets","Can I use my TSP or 401(k)?","Yes—vested balances count as assets; a loan against them must be documented with its payment considered.","26-7 Ch.4 §8"),
VQ("Assets","How are closing costs typically covered with $0 down?","Seller-paid costs (unlimited for true closing costs), seller concessions up to 4%, lender credits via pricing, gift funds, or the borrower's cash.","26-7 Ch.8"),
VQ("Assets","Does VA allow a down payment assistance program?","Yes; DPA from governmental or nonprofit entities can cover closing costs; VA has no down payment, so DPA mostly covers costs.","26-7 Ch.8; Ch.9"),
VQ("Assets","Can I use crypto proceeds?","Once converted to U.S. dollars and deposited with a documented trail; lenders differ on documentation.","Lender policy; 26-7 Ch.4 §8"),
// ---------- Property / appraisal / MPR ----------
VQ("Property","What kinds of homes can I buy with a VA loan?","Single-family homes, VA-approved condos, 2–4 unit properties (owner-occupying one), manufactured homes on permanent foundations titled as real property, new construction, and (with lender programs) homes needing repairs. No pure land, vacation or investment purchases.","26-7 Ch.3; Ch.12"),
VQ("Property","What are VA Minimum Property Requirements (MPRs)?","Standards ensuring the home is safe, structurally sound and sanitary: working mechanical systems, adequate heating, roof with remaining life, no peeling paint in pre-1978 homes, safe water supply/sewage, accessible crawl spaces, no wood-destroying insect damage, etc.","26-7 Ch.12"),
VQ("Property","How is a VA appraisal different from a conventional one?","A VA-assigned fee appraiser (via WebLGY) performs a market-value appraisal and checks MPRs. Fees are set by VA per state; typical turn times 7–14 days; the lender's SAR issues the Notice of Value (NOV).","26-7 Ch.10; Ch.13"),
VQ("Property","What is Tidewater?","If the appraiser expects the value to come in below the contract price, they notify the lender's point of contact, who has 2 business days to supply additional comparable sales before the appraisal is finalized.","Circular 26-03-11; 26-7 Ch.10"),
VQ("Property","What is a Reconsideration of Value (ROV)?","A formal request through the lender to the VA Regional Loan Center asking the appraiser/VA to reconsider the value using new comps or corrected errors; VA typically responds within 5–10 business days.","26-7 Ch.10 §11; Circular 26-24-14 (ROV process)"),
VQ("Property","What happens if the appraisal is low?","Options: negotiate the price down, pay the difference in cash, seller carries a second, or cancel under the VA escape clause (amendatory clause) with your deposit returned.","26-7 Ch.9 §5"),
VQ("Property","What is the VA escape clause?","A mandatory contract provision: the buyer is not obligated to complete the purchase if the VA value is less than the price, and the deposit is refundable; the buyer may still proceed and pay the difference.","38 CFR 36.4303(k); 26-7 Ch.9 §5"),
VQ("Property","Does VA require a home inspection?","No, but VA strongly recommends one; the appraisal is not an inspection.","26-7 Ch.12"),
VQ("Property","Does VA require a termite inspection?","In most of the Southern and Western states (including CA, NV, AZ, FL; parts of IL) a wood-destroying insect inspection is required per VA's state list. Veterans may pay for it since 2022 (previously prohibited in many states).","26-7 Ch.12 §4; Circular 26-22-10"),
VQ("Property","Who pays for repairs required by the appraisal?","Negotiable; the seller usually completes them before closing, or an escrow holdback can be set up for weather-related or minor items.","26-7 Ch.12; Ch.9"),
VQ("Property","Can I buy a fixer-upper with a VA loan?","Only if it meets MPRs at closing or repairs are completed/escrowed; some lenders offer VA Alteration & Repair (renovation) loans that finance repairs.","Circular 26-18-6; 26-7 Ch.12"),
VQ("Property","Can I buy a condo?","Yes, if the project is VA-approved (list on WebLGY) or the lender obtains approval; HOA reviews include litigation, reserves and owner-occupancy.","26-7 Ch.16"),
VQ("Property","Can I buy a manufactured home?","Yes if it is on a permanent foundation, titled as real property with the land, built after 6/15/1976 and meets MPRs; lender overlays are common.","26-7 Ch.12 §9"),
VQ("Property","Can I buy a duplex, triplex or fourplex?","Yes, if you occupy one unit; rental income from the others may help you qualify.","26-7 Ch.3 §2; Ch.4 §2.n"),
VQ("Property","Can I buy land and build?","VA construction loans exist (one-time close or two-time close) through participating lenders; the builder must be registered with VA (or exempt under 2025 changes for some loan types) and the home must meet MPRs with warranty/inspections.","26-7 Ch.7 §9; Circular 26-25-1"),
VQ("Property","Can I buy a home with solar panels?","Yes. Owned panels are fine; leased/PPA panels must be transferable and the payment counts in DTI; PACE liens must be paid off because they prime the mortgage.","26-7 Ch.9; VA Circular on PACE (26-16-18)"),
VQ("Property","What about well water and septic?","Water must be potable (test required for private wells); septic must be functioning; distances to wells per local health standards.","26-7 Ch.12 §6"),
VQ("Property","Does VA require the roof to have a certain life?","The roof must have enough remaining life to not need replacement in the near future (commonly 3–5 years) and no active leaks.","26-7 Ch.12 §2"),
VQ("Property","Can I buy a home with an unpermitted addition or ADU?","Appraisers note unpermitted areas; value may exclude them; safety issues must be corrected; local code enforcement risk is weighed by the lender.","26-7 Ch.12"),
VQ("Property","Can I buy a home with a pool?","Yes; the pool must be safe (fencing per local code) and not a hazard.","26-7 Ch.12"),
VQ("Property","How long is a VA appraisal valid?","6 months for existing construction; 12 months for proposed construction. The NOV date controls.","26-7 Ch.10 §6"),
VQ("Property","Can the appraisal be transferred to another lender?","Yes; VA appraisals belong to the case and can be transferred by the original lender via WebLGY when you switch lenders.","26-7 Ch.10"),
VQ("Property","Can I waive the appraisal?","Not on purchases; IRRRLs typically don't require one.","26-7 Ch.6; Ch.10"),
VQ("Property","Is a flood zone a problem?","No, but flood insurance is required in a Special Flood Hazard Area and the premium counts in the housing payment.","26-7 Ch.9 §6"),
VQ("Property","Can I buy a home in a 55+ community?","Yes if the veteran (or spouse) meets the community's age rules and will occupy; HOA/PUD review applies.","26-7 Ch.16"),
VQ("Property","Does VA have acreage limits?","No fixed limit; value must be supported by comparables and the property must be primarily residential.","26-7 Ch.11"),
VQ("Property","Can I buy a mixed-use property?","Yes if residential use predominates and the commercial portion does not impair the residential character or value.","26-7 Ch.11"),
VQ("Property","Can I buy a home from a family member?","Yes; the appraisal protects value; gifts of equity are allowed.","26-7 Ch.9"),
VQ("Property","What is the 'Notice of Value'?","The lender's SAR-issued document stating VA's determined value and any conditions (repairs, inspections) that must be satisfied before closing.","26-7 Ch.13"),
VQ("Property","Can the seller refuse to make MPR repairs?","Yes, but then the loan cannot close unless the buyer arranges completion (with seller permission) or an escrow; VA does not allow closing with unmet MPRs.","26-7 Ch.12"),
// ---------- Process / offer ----------
VQ("Process","How long does a VA loan take to close?","Typically 21–40 days from contract; the appraisal (7–14 days) is the main variable. Well-prepared files with a TBD approval close in 2–3 weeks.","26-7; industry data"),
VQ("Process","What is a TBD (to-be-determined) approval?","A full underwriting approval before you have a property, so only the appraisal and title remain; it makes your offer nearly as strong as cash.","Industry practice"),
VQ("Process","Why do some sellers avoid VA offers and how do I overcome that?","Myths: slow closings, strict appraisals, seller-paid fees. Counter with a fully underwritten approval, a lender call to the listing agent, a clear fact sheet, and strong terms (short contingencies). VA fees payable by seller are negotiable, not required.","VA fact sheets; 26-7 Ch.8"),
VQ("Process","Can I waive the appraisal contingency to compete?","You cannot waive the VA escape clause, but you can agree to pay an appraisal gap up to a set amount in cash.","38 CFR 36.4303(k)"),
VQ("Process","Can I use a VA loan on a short sale or REO?","Yes; MPRs still apply, and banks selling REO often won't make repairs—plan for escrow or condition negotiations.","26-7 Ch.12"),
VQ("Process","What is the 1% origination fee?","VA caps lender origination at a 1% flat fee (or itemized reasonable fees up to 1%). Discount points, appraisal, credit report, title, recording and prepaids are separate.","26-7 Ch.8 §2"),
VQ("Process","Which fees can't I pay as a veteran?","Non-allowable fees when the lender charges the 1% flat fee: processing, underwriting, document preparation, attorney fees for the lender, notary over the limit, escrow fees, settlement fees, etc. These are paid by the seller or lender.","26-7 Ch.8 §2–3"),
VQ("Process","Can I pay discount points?","Yes; points are allowable and unlimited; they can also be seller-paid outside the 4% concession cap.","26-7 Ch.8 §2"),
VQ("Process","What is the 4% seller concession rule?","Seller concessions (anything beyond normal closing costs: funding fee, prepaids, payoff of buyer debts, gifts, buydown escrows) are capped at 4% of the established reasonable value; seller-paid closing costs and points are not capped.","26-7 Ch.8 §5"),
VQ("Process","Can the seller pay off my car loan to help me qualify?","Yes—as a concession within the 4% cap. The payoff must appear on the closing disclosure.","26-7 Ch.8 §5"),
VQ("Process","Can I buy a home and keep my current one?","Yes, with second-tier entitlement and qualifying income (rental offset).","26-7 Ch.3 §4"),
VQ("Process","Do I need a real estate agent?","Not required, but recommended—especially one with VA experience (MRP designation).","—"),
VQ("Process","Can I pay my buyer's agent commission with a VA loan?","Since August 2024 VA allows veterans to pay reasonable buyer-broker fees when the seller won't; VA still encourages seller-paid compensation.","Circular 26-24-14"),
VQ("Process","Can I close remotely or while deployed?","Yes, with a VA-specific power of attorney (specific or general with VA language) and an 'alive and well' statement near closing; many states allow remote online notarization.","26-7 Ch.9 §7"),
VQ("Process","What is the Loan Estimate and when do I get it?","A TRID disclosure of estimated costs within 3 business days of application; a Closing Disclosure comes at least 3 business days before closing.","Reg Z 1026.19(e)/(f)"),
VQ("Process","Can I lock my rate before finding a home?","Some lenders offer lock-and-shop programs; most lock after contract. Lock periods should cover the expected closing date plus a cushion.","Lender policy"),
VQ("Process","What is the VA Loan Summary Sheet / 26-0286?","Lender form summarizing the loan for VA; it accompanies the closing package submitted for guaranty.","26-7 Ch.5"),
VQ("Process","Can I use a VA loan to buy from a builder?","Yes; builders must be registered with VA (for new construction guaranty) and provide a warranty; builder incentives tied to a captive lender should be negotiated to apply with any lender.","26-7 Ch.10 §13"),
VQ("Process","Can I get a VA loan after a recent job change?","Yes; same-field changes are fine, and the new employer's offer letter plus first paystub support it.","26-7 Ch.4 §2"),
VQ("Process","What's the difference between pre-qualification and pre-approval?","Pre-qualification is a conversation; pre-approval includes credit, documentation review and often underwriting (TBD approval). Sellers value underwritten approvals.","Industry practice"),
VQ("Process","Does VA require an escrow/impound account?","VA does not require it, but nearly all lenders require escrows for taxes and insurance on VA loans.","Lender policy"),
VQ("Process","Can I buy a home that is tenant-occupied?","Yes if you will occupy within 60 days (or an acceptable later date up to 12 months with justification) after the tenant vacates.","26-7 Ch.3 §5"),
VQ("Process","Can I use my VA loan with a seller carryback second?","Yes under VA's secondary financing rules: combined loans cannot exceed VA value, the second must have reasonable terms (no balloon before 5 years), and you must qualify with both payments.","26-7 Ch.9 §4"),
VQ("Process","What is the 'reasonable value'?","VA's appraised value as stated on the NOV; the loan (excluding funding fee) cannot exceed it.","26-7 Ch.10"),
VQ("Process","Can I use a VA loan to buy a home at auction?","Rarely practical: auctions usually require cash and no appraisal contingency; some bank auctions allow financing.","—"),
VQ("Process","Can I pay for an appraisal before intent to proceed?","No—TRID prohibits collecting fees other than a credit report fee before you indicate intent to proceed after receiving the Loan Estimate.","Reg Z 1026.19(e)(2)"),
VQ("Process","Can I switch lenders mid-process?","Yes; the appraisal can transfer, new disclosures are issued, and timelines may slip; weigh the benefit.","26-7 Ch.10"),
VQ("Process","What is a 'Loan Guaranty Certificate'?","The document VA issues after closing confirming the guaranty; lenders must obtain it within 60 days.","26-7 Ch.5"),
VQ("Process","Can a veteran be charged a prepayment penalty?","No. VA loans have no prepayment penalties.","38 CFR 36.4310"),
VQ("Process","How much earnest money is typical?","1–3% of price locally; it is credited at closing or refunded under the escape clause if value falls short.","Market practice"),
VQ("Process","Does VA require a survey?","Only if the lender/title company requires one; not a VA requirement.","26-7 Ch.9"),
VQ("Process","Can I buy a home with a VA loan and rent rooms to friends?","Yes, as long as you occupy it as your primary residence.","26-7 Ch.3 §5"),
// ---------- Refinance ----------
VQ("Refinance","What is an IRRRL (VA streamline)?","Interest Rate Reduction Refinance Loan: refinance an existing VA loan to a lower rate (or ARM to fixed) with minimal documentation—usually no appraisal or income verification—and a 0.5% funding fee. Requires 210 days since the first payment and 6 payments made, a net tangible benefit, and recoupment of costs within 36 months.","38 U.S.C. §3709; 26-7 Ch.6; Circular 26-19-22"),
VQ("Refinance","Can I take cash out with an IRRRL?","No. IRRRLs are rate/term only; up to $500 incidental cash may be allowed. Use a VA cash-out for equity.","26-7 Ch.6"),
VQ("Refinance","What is the net tangible benefit for an IRRRL?","Fixed-to-fixed: rate at least 0.5% lower; fixed-to-ARM: at least 2% lower; ARM-to-fixed: any lower rate (can be up to 1% higher in some cases—verify); plus recoupment of costs ≤36 months.","38 U.S.C. §3709(a)-(b)"),
VQ("Refinance","Do I have to live in the home to do an IRRRL?","No. You must certify that you previously occupied it; current occupancy isn't required (a rented former residence qualifies).","26-7 Ch.6 §1"),
VQ("Refinance","Can I roll closing costs into the IRRRL?","Yes, including the funding fee and up to 2 discount points; the recoupment test must still pass.","26-7 Ch.6"),
VQ("Refinance","How much can I cash out with a VA cash-out refinance?","Up to 100% of appraised value including the funding fee by statute; most lenders cap at 90%. Full underwriting, appraisal and NTB apply.","38 CFR 36.4306; Circular 26-19-05"),
VQ("Refinance","Can I refinance a non-VA loan into a VA loan?","Yes—a VA cash-out (Type I if the new loan doesn't exceed the payoff, Type II if it does); you must occupy the home and have entitlement.","38 CFR 36.4306"),
VQ("Refinance","What are the seasoning rules?","Both IRRRL and cash-out require the later of 210 days from the first payment due date or 6 monthly payments made on the loan being refinanced.","38 U.S.C. §3709(c)"),
VQ("Refinance","What is the recoupment test?","All closing costs (excluding prepaids/escrows and the funding fee) must be recouped from the monthly P&I savings within 36 months.","38 U.S.C. §3709(a)(1)"),
VQ("Refinance","Can I remove my ex-spouse with an IRRRL?","An IRRRL can remove a co-borrower only if the remaining borrower is the veteran (credit-qualifying may be required); a cash-out with full underwriting is the common route for buyouts.","26-7 Ch.6"),
VQ("Refinance","Can I refinance to a shorter term?","Yes; shorter terms with a higher payment can still be an IRRRL if the payment increase is ≤20% (otherwise credit/income verification applies).","26-7 Ch.6 §1"),
VQ("Refinance","How often can I IRRRL?","Each time the seasoning and NTB tests are met; repeated churning is monitored, and lenders must disclose comparisons.","38 U.S.C. §3709"),
VQ("Refinance","Does the funding fee apply to refinances?","IRRRL 0.5%; cash-out 2.15% first use / 3.3% subsequent; exemptions apply.","38 U.S.C. §3729"),
VQ("Refinance","Can I pay off a second mortgage or HELOC with an IRRRL?","No; the IRRRL only refinances the VA first lien. A cash-out can consolidate liens.","26-7 Ch.6"),
VQ("Refinance","What disclosures must I receive on a VA cash-out?","A loan comparison and home-equity disclosure at application and closing showing payoff amounts, new terms, and the reduction in home equity.","38 CFR 36.4306(a)(5)"),
VQ("Refinance","Can I do a cash-out on a rental I used to live in?","No. VA cash-out requires current occupancy as a primary residence.","38 CFR 36.4306"),
VQ("Refinance","Will an IRRRL reset my 30 years?","The new term can be up to the original term plus 10 years (max 30); you can choose a shorter term.","26-7 Ch.6"),
VQ("Refinance","Can I use an IRRRL if I'm behind on payments?","The loan must be current; lenders may allow one 30-day late in the last 12 months with VA approval in some cases.","26-7 Ch.6 §1"),
VQ("Refinance","Is an appraisal ever required on an IRRRL?","VA doesn't require one; some lenders use AVMs or require appraisals by overlay.","26-7 Ch.6"),
VQ("Refinance","Can I refinance a VA loan into a conventional loan?","Yes, which frees your entitlement once the VA loan is paid off (restoration request required).","26-7 Ch.2 §9"),
// ---------- Assumptions ----------
VQ("Assumption","Are VA loans assumable?","Yes. Loans closed after March 1, 1988 require servicer approval of the buyer's credit/income; the assumer pays a 0.5% funding fee (unless exempt) and a processing fee. The buyer need not be a veteran.","38 U.S.C. §3714; 26-7 Ch.5"),
VQ("Assumption","What happens to my entitlement if a non-veteran assumes my loan?","It remains tied to the loan until it is paid off; you also need a release of liability (VA Form 26-6381) to avoid responsibility for the debt.","26-7 Ch.5 §4"),
VQ("Assumption","How is the equity gap handled on an assumption?","The buyer pays the difference between price and loan balance in cash or with a second lien (lender-dependent); VA circulars allow junior liens meeting standards.","Circular 26-24-17"),
VQ("Assumption","How long does an assumption take?","45–120 days depending on the servicer; servicers must process within 45 days after a complete package by statute, but delays are common.","38 U.S.C. §3714"),
VQ("Assumption","Can my ex-spouse assume the loan after divorce?","Yes; a divorce-related assumption with the veteran's entitlement remaining (unless the ex is a veteran who substitutes) requires servicer credit approval; funding fee is waived for certain divorce transfers.","26-7 Ch.5"),
VQ("Assumption","What fees can the servicer charge for an assumption?","$300 plus credit report costs for automatic-authority servicers ($250 for VA prior approval), plus the 0.5% funding fee.","26-7 Ch.5 §3"),
// ---------- Occupancy / PCS ----------
VQ("Occupancy","How soon must I move in?","Within 60 days of closing, or up to 12 months with justification (e.g., deployment, completion of repairs) accepted by the lender.","26-7 Ch.3 §5"),
VQ("Occupancy","Can my spouse satisfy occupancy while I'm deployed?","Yes; spouse occupancy counts. A dependent child can satisfy it in certain cases with an attorney-in-fact.","26-7 Ch.3 §5"),
VQ("Occupancy","Can I buy near my next duty station before PCS orders are final?","Lenders can use projected income/BAH with orders; without orders, you must qualify on current income and plan occupancy within 60 days (or justify a later date).","26-7 Ch.3 §5; Ch.4 §2"),
VQ("Occupancy","Can I rent out my VA home later?","Yes—after satisfying the occupancy intent, you may rent it; keep paying the loan. Nothing in VA rules requires selling.","26-7 Ch.3 §5"),
VQ("Occupancy","Can I buy a second home with VA?","Only as a new primary residence (e.g., job relocation) with second-tier entitlement; vacation homes are not eligible.","26-7 Ch.3 §4–5"),
VQ("Occupancy","How does VA define primary residence?","The home you live in most of the year; you certify intent at application and closing. Misrepresenting occupancy is fraud.","26-7 Ch.3 §5"),
VQ("Occupancy","Can I buy a home in a different city than my current base?","Yes if you will occupy it within the required time (e.g., PCS orders, retirement, remote work arrangements); the lender assesses reasonableness.","26-7 Ch.3 §5"),
VQ("Occupancy","I'm retiring in 6 months. Can I buy in my retirement city now?","Yes, with retirement orders/pension evidence and occupancy within 12 months justified.","26-7 Ch.3 §5; Ch.4 §2"),
// ---------- Disability / benefits ----------
VQ("Disability","How does a VA disability rating affect my loan?","Any compensable rating (10%+) exempts you from the funding fee; disability income counts (grossed up); many states offer property-tax exemptions that lower PITI.","38 U.S.C. §3729(c); state statutes"),
VQ("Disability","What is the California disabled-veteran property tax exemption?","Veterans rated 100% (or unemployable) get a basic exemption (~$175k+ assessed value, indexed) or a low-income exemption (~$262k+); it reduces property taxes used in qualifying once in effect.","CA Rev & Tax Code §205.5"),
VQ("Disability","What about Florida, Nevada, Arizona and Illinois?","FL: total exemption for 100% P&T; partial for 10%+ ($5,000). NV: partial exemption by rating percentage. AZ: limited exemption for disabled veterans (expanded 2023). IL: exemptions scaled by rating (30–49% $2,500; 50–69% $5,000; 70%+ full for primary residence).","State statutes (FL 196.081; NV 361.091; AZ 42-11111; IL 35 ILCS 200/15-169)"),
VQ("Disability","Can I use the Specially Adapted Housing (SAH) grant with a VA loan?","Yes. SAH/SHA grants can be combined with a VA loan to buy or modify an accessible home.","38 U.S.C. §2101; 26-7 Ch.7"),
VQ("Disability","Does a pending disability claim get me the exemption?","Not at closing unless VA issues a pre-discharge rating or determination; if the award is retroactive to before closing, the fee is refunded.","26-7 Ch.8 §8.e"),
VQ("Disability","Can VA disability income alone qualify me?","Yes, if residual and DTI work; it's stable and non-taxable (grossed up).","26-7 Ch.4 §2"),
// ---------- Surviving spouse / Guard / Reserve ----------
VQ("Guard & Reserve","How do Guard/Reserve members prove eligibility?","Current members: statement of service from the unit; discharged members: NGB-22/23 (Guard) or points statement and discharge (Reserve); 6 years or 90 days Title 10 (30 consecutive) or qualifying Title 32.","26-7 Ch.2 §3"),
VQ("Guard & Reserve","Is the funding fee higher for Reservists?","Not anymore. Since 2020 the fee is the same for Reserve/Guard and active duty.","Blue Water Navy Act; 38 U.S.C. §3729"),
VQ("Guard & Reserve","Does drill pay count as income?","Yes, with a history and likelihood of continuance (2 years typical).","26-7 Ch.4 §2"),
VQ("Surviving spouse","Is the funding fee waived for surviving spouses?","Yes if receiving DIC (Dependency and Indemnity Compensation).","38 U.S.C. §3729(c)"),
VQ("Surviving spouse","Can a surviving spouse refinance the veteran's VA loan?","Yes—an IRRRL is possible if the spouse was a co-obligor; otherwise, eligibility via 26-1817 allows a new VA loan.","26-7 Ch.2 §4; Ch.6"),
// ---------- Construction / renovation / multi-unit / condo ----------
VQ("Construction","Does VA do construction loans?","Yes, through lenders offering one-time close (OTC) or two-time close; VA guarantees the permanent loan; the builder provides a 1-year warranty and inspections/CO; no payments during construction on OTC.","26-7 Ch.7 §9; Circular 26-18-7"),
VQ("Construction","Can I be my own builder?","Owner-builder is generally not allowed on VA construction loans; a licensed builder with a fixed-price contract is required.","Lender policy; 26-7 Ch.7"),
VQ("Construction","Can I finance repairs with a VA loan?","Some lenders offer VA Alteration & Repair loans up to ~$50k–$75k for non-structural repairs; otherwise repairs must be completed before closing or escrowed.","Circular 26-18-6"),
VQ("Construction","Can I buy a lot with a VA loan?","Only as part of a simultaneous construction loan; VA does not finance land alone.","26-7 Ch.3 §1"),
VQ("Construction","Does a new build need a builder ID?","For regular VA loans the builder ID requirement was removed in 2025 (Circular 26-25-1); still required for SAH and NADL.","Circular 26-25-1"),
VQ("Multi-unit","How does VA treat a 2–4 unit purchase?","You must occupy one unit; 75% of market rents from the others can be used; VA may require 6 months reserves and evidence of landlord/management ability for income use.","26-7 Ch.4 §2.n"),
VQ("Multi-unit","Does the funding fee change for multi-units?","No; same purchase tiers.","38 U.S.C. §3729"),
VQ("Condo","How do I check if a condo is VA-approved?","Search the VA condo approval list in WebLGY (public lookup) by project name/city; if not approved, the lender can submit the project for approval (2–6 weeks).","26-7 Ch.16"),
VQ("Condo","What makes a condo project ineligible?","Pending litigation affecting safety/structure, inadequate reserves, high delinquencies, single-entity ownership >35–49%, high commercial space, restrictions on transfer that conflict with VA rules.","26-7 Ch.16 §2"),
VQ("Condo","Is HOA litigation an automatic no?","No; VA reviews the nature—minor disputes may be acceptable, structural/financial litigation usually is not.","26-7 Ch.16"),
VQ("Manufactured","What is needed for a manufactured home?","HUD code (post-1976), permanent foundation (engineer cert), real-property title, not moved from a prior site (except from dealer), skirting/tie-downs; appraiser with MH competency.","26-7 Ch.12 §9"),
VQ("Manufactured","Can I buy a manufactured home in a park?","VA allows leasehold if the lease term exceeds the loan term; practically, CalVet is often the path in California parks.","26-7 Ch.12; CalVet"),
// ---------- Derogatory events ----------
VQ("Derogatory","Can I get a VA loan after a deed-in-lieu?","Generally after 2 years, similar to foreclosure; earlier with extenuating circumstances.","26-7 Ch.4 §7"),
VQ("Derogatory","What are 'extenuating circumstances'?","Events beyond your control—serious illness, death of a wage earner, job loss from downsizing—that caused the derogatory event and have since resolved, documented with evidence.","26-7 Ch.4 §7.e"),
VQ("Derogatory","How does VA treat a judgment?","Must be paid or under a repayment plan with a history; unpaid judgments must be resolved before closing (title issues).","26-7 Ch.4 §7"),
VQ("Derogatory","I owe VA money from a prior loan. What now?","Resolve with the VA Debt Management Center (repayment plan or compromise); CAIVRS must be clear; entitlement tied to the loss remains until repaid.","26-7 Ch.4 §7.h"),
VQ("Derogatory","Do federal student loans in default block a VA loan?","Yes via CAIVRS until rehabilitated or consolidated out of default.","26-7 Ch.4 §7.h"),
// ---------- Jumbo / pricing ----------
VQ("Jumbo","What is a VA jumbo loan?","A VA loan above the conforming limit; with full entitlement no down payment is required, but lenders set caps and pricing tiers and may require reserves or a small down payment above $1–1.5M.","Blue Water Navy Act; lender matrices"),
VQ("Jumbo","Is VA jumbo cheaper than conventional jumbo?","Often yes—no MI, lower rates, and $0 down; compare total cost.","Market pricing"),
VQ("Pricing","Why do VA rates differ from conventional?","VA loans are pooled in Ginnie Mae securities with a full federal guaranty, which usually yields lower rates than conventional loans.","Ginnie Mae"),
VQ("Pricing","What is a temporary buydown and can VA buyers use one?","A 2-1 or 3-2-1 buydown funded by the seller/builder/lender lowers payments in years 1–3; the veteran qualifies at the note rate; VA permits when funded by third parties.","Circular 26-23-26? verify; 26-7 Ch.8 §5"),
VQ("Pricing","Can I choose an ARM?","Yes—VA hybrid ARMs (3/1, 5/1, 7/1, 10/1) with 1/1/5 caps (3/1 & 5/1) or 2/2/6 (7/1,10/1); qualify at the note rate.","38 CFR 36.4312(d)"),
VQ("Pricing","Can I get a 15- or 20-year VA loan?","Yes; any term up to 30 years (30 years 32 days).","38 CFR 36.4310"),
// ---------- State / local ----------
VQ("State programs","What is CalVet and how is it different?","California's state veteran home loan program: a direct lender using VA guaranty or its own funds, flexible underwriting (no hard FICO floor), manufactured homes in parks, construction/land, and built-in home/fire insurance. Often slower but accommodating.","CalVet Home Loans guide"),
VQ("State programs","Does Nevada have veteran programs?","Nevada Housing Division's Home Is Possible for Heroes offers a below-market rate for veterans/active duty with optional DPA; combine with VA.","NHD HIP for Heroes"),
VQ("State programs","Arizona?","Home Plus (statewide DPA 3–5%) works with VA; disabled-veteran property tax exemption expanded in 2023.","AZ IDA Home Plus"),
VQ("State programs","Illinois?","IHDA Access programs offer DPA with VA firsts; IL disabled-veteran exemptions are among the most generous (full exemption at 70%+).","IHDA; 35 ILCS 200/15-169"),
VQ("State programs","Florida?","Salute Our Soldiers (lower rate + DPA) and Hometown Heroes (up to $35k 0% deferred) can layer with VA; total property tax exemption for 100% P&T veterans.","Florida Housing; FL 196.081"),
// ---------- Servicing / after closing ----------
VQ("Servicing","What if I can't make my payments?","Contact the servicer early; VA loan technicians (877-827-3702) can intervene; options include forbearance, repayment plans, loan modification, VA partial claim (VASP program as of 2024), deed-in-lieu, or compromise sale.","38 CFR 36.4300 series; VA Servicing Purchase (VASP)"),
VQ("Servicing","Does VA have foreclosure protections?","Yes—servicers must evaluate home-retention options; VA can purchase and modify loans (VASP) and offers a 120-day foreclosure moratorium in certain programs. SCRA protections apply during active duty.","VASP (2024); SCRA 50 U.S.C. §3953"),
VQ("Servicing","Can I pay extra principal?","Yes, any amount at any time with no penalty.","38 CFR 36.4310"),
VQ("Servicing","How do I get a release of liability after selling with an assumption?","Apply to the servicer with the assumer's approval; VA Form 26-6381 release of liability and entitlement substitution if the buyer is a veteran.","26-7 Ch.5 §4"),
VQ("Servicing","Will my loan be sold?","Likely; servicing transfers are common and don't change your terms. You get a 15-day notice.","RESPA §6"),
VQ("Servicing","Can I remove escrow later?","Lender policy; many allow after 12 months with LTV conditions; VA doesn't prohibit.","Lender policy"),
VQ("Servicing","What is SCRA and how does it help?","Servicemembers Civil Relief Act: 6% interest cap on pre-service debts, foreclosure protections during and 1 year after active duty, lease terminations on PCS.","50 U.S.C. §3901 et seq."),
VQ("Servicing","Does VA offer a hardship program after a natural disaster?","Yes—servicers offer forbearance and VA issues circulars after major disasters; FEMA assistance may apply.","VA disaster circulars"),
];
VA_QA.push(
// ---------- Comparisons & myths ----------
VQ("Comparisons","VA vs FHA — which is better for a veteran?","VA nearly always: $0 down vs 3.5%, no monthly mortgage insurance vs FHA's life-of-loan MIP, lower rates, no loan limit with full entitlement, and more lenient DTI via residual income. FHA can win only when VA overlays block the file (rare with no-overlay lenders) or the buyer isn't VA-eligible.","26-7; HUD 4000.1 comparison"),
VQ("Comparisons","VA vs conventional with 20% down?","Even with 20% available, VA often wins on rate (Ginnie Mae pricing) and lets the veteran keep the cash invested; the funding fee (waived if rated) is the main cost. Compare total 5–7 year cost with the Loan Comparison calculator.","Market pricing; 38 U.S.C. §3729"),
VQ("Comparisons","Is a VA loan more expensive because of the funding fee?","Not usually. The one-time 2.15% fee is typically less than years of PMI/MIP, and it's waived for rated veterans and financed for everyone else.","38 U.S.C. §3729"),
VQ("Comparisons","Myth: VA appraisals are stricter.","VA appraisers check Minimum Property Requirements—safety, structure, sanitation—similar to FHA's standards; a well-maintained home passes. Most 'strict' stories are peeling paint, missing handrails or water-heater straps that take an afternoon to fix.","26-7 Ch.12"),
VQ("Comparisons","Myth: VA loans take longer to close.","VA loans close in about the same time as conventional (average 40-ish days industry-wide, far faster with prepared files). The appraisal is the only VA-specific timing item.","ICE/Ellie Mae Origination Insight (historical)"),
VQ("Comparisons","Myth: Sellers have to pay the buyer's closing costs on VA.","False. Sellers are not required to pay anything; only certain 'non-allowable' fees cannot be charged to the veteran, and lenders routinely absorb those.","26-7 Ch.8"),
VQ("Comparisons","Myth: You can only use VA once.","False—entitlement is restorable and reusable for life, and second-tier entitlement allows concurrent loans.","26-7 Ch.2 §9"),
VQ("Comparisons","Myth: VA loans are only for first homes or cheap homes.","False—no VA loan limit with full entitlement; VA jumbo loans to several million close routinely.","Blue Water Navy Act"),
VQ("Comparisons","Myth: VA loans require perfect credit.","False—no VA minimum score; lenders set overlays, some as low as 500–580.","26-7 Ch.4 §7"),
VQ("Comparisons","Myth: The VA lends the money.","Private lenders fund VA loans; VA guarantees 25% of the loan against default, which is what enables $0 down and no MI.","38 U.S.C. §3703"),
VQ("Comparisons","When would FHA beat VA?","Buyer not eligible; non-occupant co-borrower needed at 96.5% (VA joint loans require a down payment on the non-vet share); 3–4 unit with lender overlays; or a condo approved by FHA but not VA.","26-7 Ch.7; HUD 4000.1"),
VQ("Comparisons","When would conventional beat VA?","Rarely: investment property purchases (VA can't), second homes, or when a veteran has partial entitlement and a large down payment makes conventional pricing equal.","26-7 Ch.3"),
// ---------- Closing costs ----------
VQ("Closing costs","What closing costs can a veteran pay?","Appraisal, credit report, title examination and insurance, recording fees, survey (if required), prepaid taxes/insurance/interest, the 1% origination fee (or itemized up to 1%), discount points, VA funding fee, termite inspection (since 2022), and reasonable third-party fees on VA's allowable list.","26-7 Ch.8 §2"),
VQ("Closing costs","What are typical total closing costs on a VA purchase?","Around 2–4% of the price before the funding fee, depending on title/escrow fees, prepaids and points; the funding fee is additional but usually financed.","Market data"),
VQ("Closing costs","Can the lender charge an underwriting fee?","Only if it does not charge the 1% flat fee and the itemized fees total ≤1%; otherwise underwriting is a non-allowable fee the lender/seller absorbs.","26-7 Ch.8 §2"),
VQ("Closing costs","What is the difference between 'closing costs' and 'concessions'?","Closing costs are the normal charges to complete the loan; concessions are extras the seller gives (paying the funding fee, prepaids beyond normal, paying off buyer debts, gifts, buydown escrows). Seller-paid closing costs are unlimited; concessions are capped at 4%.","26-7 Ch.8 §5"),
VQ("Closing costs","Can I ask for 6% from the seller?","Yes—e.g., 4% in concessions plus closing costs/points; structure the addendum in two buckets so nothing is lost to the cap.","26-7 Ch.8 §5"),
VQ("Closing costs","What is a lender credit?","A credit toward closing costs in exchange for a slightly higher rate; it is not a seller concession and has no VA cap.","Reg Z; 26-7 Ch.8"),
VQ("Closing costs","Can the funding fee be paid in cash instead of financed?","Yes; paying it in cash lowers the loan amount and payment slightly.","26-7 Ch.8 §8"),
VQ("Closing costs","What prepaids will I see?","Homeowners insurance premium (first year), initial escrow deposit (2–3 months taxes/insurance), prepaid interest from funding to month-end, and HOA dues proration if applicable.","TRID; 26-7 Ch.8"),
VQ("Closing costs","Can the seller pay my HOA transfer fees?","Yes, as closing costs (not concessions) if customarily paid by the buyer, or as part of the seller's costs.","26-7 Ch.8"),
VQ("Closing costs","Can the agent pay part of my closing costs?","Yes, as a commission credit shown on the CD, counted as a concession if beyond closing costs (within 4%).","26-7 Ch.8 §5"),
VQ("Closing costs","Is there a VA cap on title fees?","No specific cap; fees must be reasonable and customary; the lender cannot mark them up.","26-7 Ch.8 §2"),
VQ("Closing costs","What is the 'allowable itemized fees up to 1%' rule?","If the lender doesn't charge the 1% flat fee, it may itemize origination-type charges (application, processing, underwriting, document prep) as long as the total does not exceed 1% of the loan.","26-7 Ch.8 §2"),
VQ("Closing costs","Can I pay a brokerage fee (buyer's agent)?","Yes since 2024 (Circular 26-24-14), if reasonable and customary and the seller/agent won't cover it; it cannot be financed in the loan.","Circular 26-24-14"),
// ---------- Offer strategy for VA buyers ----------
VQ("Offers","How do I make a VA offer competitive?","Fully underwritten approval; short contingency windows; appraisal-gap commitment in cash; flexible closing/rent-back (≤60 days); lender call to the listing agent; VA fact sheet; ask for seller-paid costs only where market allows.","VA fact sheets; market practice"),
VQ("Offers","Can I offer over asking and still use VA?","Yes; if the appraisal comes in lower, you cover the gap in cash, renegotiate, or exit under the escape clause.","26-7 Ch.9 §5"),
VQ("Offers","Should I waive inspection?","Never waive a home inspection entirely; VA MPRs are not an inspection. You can shorten the window.","26-7 Ch.12"),
VQ("Offers","Can I ask the seller to pay a temporary buydown?","Yes; the escrow is a concession within the 4% cap; VA buyers qualify at the note rate.","26-7 Ch.8 §5"),
VQ("Offers","What addendum language should a VA offer include?","The VA escape clause (amendatory clause) is mandatory; also specify who pays non-allowable fees, termite, and any seller concession buckets.","38 CFR 36.4303(k)"),
VQ("Offers","Can I include an appraisal-gap clause?","Yes: 'Buyer will pay up to $X above the VA appraised value from own funds'—it coexists with the escape clause for amounts beyond X.","38 CFR 36.4303(k)"),
VQ("Offers","How do I respond when a listing says 'no VA'?","Discrimination against VA financing isn't illegal in most states (some states and fair-housing rules limit it when tied to military status—e.g., California's AB 1289 added source-of-income protections for veterans in some contexts). Educate the listing agent with data and an underwritten approval.","State law; VA fact sheet"),
VQ("Offers","Can I buy a home that needs a new roof?","Only if the roof is replaced or escrowed before closing, or you use a renovation product.","26-7 Ch.12"),
VQ("Offers","How do I handle multiple-offer situations as a VA buyer?","Lead with the lender call, proof of underwriting, a gap commitment, and flexible terms; a slightly higher price with seller-paid costs can net the seller the same while helping you.","Market practice"),
// ---------- Timelines & steps ----------
VQ("Timeline","What are the steps of a VA purchase from start to finish?","1) COE and pre-approval (TBD underwriting), 2) house hunting with a VA-savvy agent, 3) offer with escape clause, 4) appraisal via WebLGY within days of contract, 5) processing/underwriting conditions, 6) NOV and repairs if any, 7) clear to close, 8) Closing Disclosure 3 business days before signing, 9) closing/funding, 10) VA guaranty issued within 60 days.","26-7 Ch.3–13"),
VQ("Timeline","How long does the COE take?","Instant to a few minutes through the lender's WebLGY in most cases; manual requests 1–3 weeks.","26-7 Ch.2 §3"),
VQ("Timeline","How long is the appraisal turn time?","VA sets timeliness standards by state (often 7–10 business days); rural areas and busy seasons take longer.","26-7 Ch.10"),
VQ("Timeline","When should I lock my rate?","After the contract is signed and the closing date is known; choose a lock period covering closing plus a cushion.","Lender policy"),
VQ("Timeline","What delays VA loans most?","Late appraisal orders, missing military documents (COE/LES), unaddressed MPR repairs, HOA/condo approvals, and title issues such as solar liens.","Industry data"),
// ---------- Military specifics ----------
VQ("Military","Can I buy before I arrive at my new duty station?","Yes, with PCS orders; lenders use the new station's BAH and allow occupancy upon arrival (within 60 days or justified).","26-7 Ch.3 §5; Ch.4 §2"),
VQ("Military","Does a deployment stop my loan?","No; use a VA-compliant POA, e-signatures/RON where allowed, and provide an alive-and-well statement before closing.","26-7 Ch.9 §7"),
VQ("Military","What is an 'alive and well' statement?","A written confirmation from the servicemember (or command) close to closing that the deployed veteran is alive and not missing, required when a POA is used.","26-7 Ch.9 §7"),
VQ("Military","Can I count hazardous-duty or flight pay?","Yes, if it is likely to continue (orders/history); special pays tied to a temporary assignment may be excluded.","26-7 Ch.4 §2.e"),
VQ("Military","Does living in the barracks affect BAH use?","BAH-with-dependents is paid regardless; single members in barracks don't receive BAH until authorized to live off base—lenders need the LES showing BAH or an authorization letter.","DoD FMR Vol.7A; 26-7 Ch.4"),
VQ("Military","Can I use my VA loan while stationed overseas to buy stateside?","Yes if a spouse will occupy, or you will occupy within 12 months on return with justification.","26-7 Ch.3 §5"),
VQ("Military","Do I lose VA eligibility if I'm discharged with a General discharge?","No—general under honorable conditions is acceptable.","26-7 Ch.2 §1"),
VQ("Military","Does time in the Delayed Entry Program count?","No; only active service counts.","26-7 Ch.2"),
VQ("Military","Can I get a VA loan after a medical separation with severance?","Yes if the discharge was other than dishonorable; disability severance may create an offset but not eligibility issues.","26-7 Ch.2"),
VQ("Military","How does a PCS affect a home I own with a VA loan?","Keep it as a rental (second-tier entitlement for the next home), sell (restoration), or let a veteran assume it (substitution).","26-7 Ch.2 §9; Ch.5"),
VQ("Military","Can I buy a home with my VA loan at a joint base in another state before I retire?","Yes with retirement orders and justification for occupancy within 12 months.","26-7 Ch.3 §5"),
VQ("Military","Do SCRA interest caps apply to a new VA mortgage?","No—SCRA's 6% cap applies to debts incurred before active service; a loan taken during service is not covered.","50 U.S.C. §3937"),
VQ("Military","Can I terminate a lease to buy a home?","SCRA allows lease termination with PCS orders of 90+ days or deployment; not for a voluntary purchase without orders.","50 U.S.C. §3955"),
// ---------- Co-borrowers / vesting ----------
VQ("Co-borrowers","Can I add my fiancé to the loan?","A non-spouse, non-veteran co-borrower makes it a joint loan: VA guarantees only the veteran's share and lenders require a down payment (typically 12.5%) on the non-veteran's half; prior VA approval required.","26-7 Ch.7 §3"),
VQ("Co-borrowers","Can my parent co-sign without being on title?","VA requires co-borrowers to take title; a non-occupant non-veteran co-signer is treated as a joint loan with the down payment rule.","26-7 Ch.7"),
VQ("Co-borrowers","Can I hold title in a trust?","Yes—revocable living trusts are acceptable if the veteran is the trustee/beneficiary and occupies; lenders review the trust.","26-7 Ch.9 §2"),
VQ("Co-borrowers","Can I hold title in an LLC?","No for VA loans; individual (or trust) vesting is required because of occupancy and guaranty rules.","26-7 Ch.9"),
VQ("Co-borrowers","Can two unmarried veterans buy together?","Yes, each using entitlement; VA prior approval is required for joint loans with non-spouses.","26-7 Ch.7"),
VQ("Co-borrowers","My spouse has an ITIN, not an SSN. Can they be on the loan?","Lender-dependent; VA requires the co-borrower to meet the lender's credit standards; many lenders require an SSN.","26-7 Ch.7"),
VQ("Co-borrowers","Does a spouse's bankruptcy affect my VA loan?","Only if the spouse is on the loan or in a community-property state their debts count; their bankruptcy itself isn't yours.","26-7 Ch.4 §5"),
// ---------- Divorce / death ----------
VQ("Divorce","Who keeps the VA loan in a divorce?","Either spouse can keep the home by refinancing or assuming; if the non-veteran ex keeps it, the veteran's entitlement stays tied up until the loan is paid off (release of liability still recommended).","26-7 Ch.5; Ch.2 §9"),
VQ("Divorce","Can my ex-spouse assume my VA loan?","Yes, with servicer credit approval; no funding fee on divorce-related assumptions in many cases; the veteran should obtain a release of liability.","26-7 Ch.5"),
VQ("Divorce","How does a buyout work with VA?","VA cash-out refinance (up to 100% statutory, 90% lender) to pay the ex-spouse; or a conventional 'rate/term' refi treating the buyout per decree.","38 CFR 36.4306; Fannie B2-1.3-02"),
VQ("Divorce","Is a court order enough to remove me from the loan?","No—only a refinance, assumption with release, or payoff removes liability; the decree binds the spouses, not the lender.","Contract law; 26-7 Ch.5"),
VQ("Death","What happens to the VA loan when the veteran dies?","Heirs can keep paying, assume, refinance or sell; the surviving spouse co-obligor can IRRRL; VA guaranty continues. Life insurance (VMLI for SAH recipients) may apply.","26-7 Ch.5; 38 U.S.C. §2106"),
// ---------- Numbers & examples ----------
VQ("Examples","Example: $500,000 purchase, first use, $0 down — what's the loan amount?","Base loan $500,000; funding fee 2.15% = $10,750; total loan $510,750 if financed. Exempt veterans: $500,000.","38 U.S.C. §3729"),
VQ("Examples","Example: remaining entitlement after a $300,000 VA loan in a $832,750 county.","Max guaranty = 25% × $832,750 = $208,187; used = 25% × $300,000 = $75,000; remaining = $133,187; $0-down ceiling = $532,750 for a new purchase.","26-7 Ch.3 §4"),
VQ("Examples","Example: residual income for a family of 4 in the West on a $600k loan.","Required residual $1,117; if DTI exceeds 41%, the lender needs $1,340 (120%).","26-7 Ch.4 §9"),
VQ("Examples","Example: seller credit of $30,000 on a $600,000 price (5%).","Up to 4% ($24,000) may be concessions (funding fee $12,900 + prepaids + debt payoff); the remaining $6,000 and more can go to closing costs or discount points without limit.","26-7 Ch.8 §5"),
VQ("Examples","Example: IRRRL recoupment.","Costs $5,400 (excluding prepaids/fee), monthly P&I savings $180 → recoupment 30 months (passes ≤36).","38 U.S.C. §3709"),
VQ("Examples","Example: joint loan with a non-veteran friend on $400,000.","VA guarantees the veteran's half ($200,000 at 25% = $50,000 guaranty); lenders typically require 12.5% down on the non-veteran's half = $25,000.","26-7 Ch.7 §3"),
// ---------- Insurance / taxes ----------
VQ("Insurance & taxes","Does VA require homeowners insurance?","Yes, hazard insurance covering the replacement cost or loan amount, with the lender as mortgagee; flood insurance in SFHAs.","26-7 Ch.9 §6"),
VQ("Insurance & taxes","Is mortgage insurance required?","No. VA loans have no monthly MI regardless of down payment.","38 U.S.C. §3703"),
VQ("Insurance & taxes","Can my property taxes be lower as a veteran?","Many states offer exemptions for disabled veterans (CA, NV, AZ, IL, FL all do, with different thresholds) and some for all veterans (e.g., certain counties); apply with the county assessor after closing.","State statutes"),
VQ("Insurance & taxes","Is the interest tax-deductible?","Mortgage interest on a primary residence is deductible for itemizers up to the $750,000 acquisition-debt limit (current law); consult a CPA.","IRC §163(h)"),
VQ("Insurance & taxes","Do I pay property taxes through escrow?","Typically yes; the lender collects monthly and pays the county; impounds are standard on VA loans.","Lender policy"),
VQ("Insurance & taxes","What is Mello-Roos and does VA allow it?","A California special tax (CFD) in newer communities; it's included in the housing payment for qualifying and must be disclosed; VA allows it.","CA Gov Code §53311 et seq."),
VQ("Insurance & taxes","Does VA require wind/hurricane insurance in Florida?","If the hazard policy excludes wind, a separate wind policy is required by lenders; flood if in an SFHA.","Lender policy; 26-7 Ch.9"),
// ---------- Lender selection / overlays ----------
VQ("Lenders","What is a lender overlay?","A lender's own rule stricter than VA's (e.g., 620 minimum score, 50% DTI cap, 2-unit max). Overlays are the main reason VA files get declined; moving to a lender without that overlay often solves it.","Industry practice; 26-7"),
VQ("Lenders","Which lenders have no FICO overlay for VA?","It changes; some lenders accept 500–580 with manual underwriting (e.g., Carrington, Loan United, Mortgage Solutions Financial have historically). Verify current matrices.","Lender matrices"),
VQ("Lenders","What is automatic authority vs prior approval?","Lenders with VA automatic authority underwrite and close without VA review; others (or certain loans like joint loans) need VA prior approval, adding time.","26-7 Ch.1"),
VQ("Lenders","What is a SAR?","Staff Appraisal Reviewer—the lender employee VA approves to review appraisals and issue the Notice of Value under LAPP.","26-7 Ch.13"),
VQ("Lenders","Should I use a broker or a direct lender?","Brokers access many VA lenders' niches (no-overlay options) and pricing; direct lenders control the process. A VA-specialist broker is often best for tough files.","—"),
VQ("Lenders","Why was I declined by one lender and approved by another?","Overlays and underwriter judgment differ; VA's rules are the floor, not the ceiling.","26-7"),
VQ("Lenders","Can a credit union do VA loans?","Yes, if VA-approved (Navy Federal, USAA, PenFed and many others).","26-7 Ch.1"),
VQ("Lenders","How do I file a complaint about a lender?","Contact the VA Regional Loan Center or file with the CFPB; VA monitors lender performance.","va.gov; CFPB"),
// ---------- Forms & documents ----------
VQ("Forms","What documents do I need to apply?","ID, COE (lender pulls), DD-214 or statement of service, 2 recent LES/paystubs, 2 years W-2s (or tax returns if self-employed), 2 months bank statements, award letters for benefit income, divorce decree if applicable, purchase contract.","26-7 Ch.4"),
VQ("Forms","What is VA Form 26-1880?","Request for a Certificate of Eligibility (and restoration of entitlement).","26-7 Ch.2"),
VQ("Forms","What is VA Form 26-1802a?","The HUD/VA Addendum to the Uniform Residential Loan Application, signed by the veteran and lender.","26-7 Ch.5"),
VQ("Forms","What is VA Form 26-6393?","Loan Analysis—where the underwriter computes residual income, ratios and lists compensating factors.","26-7 Ch.4 §10"),
VQ("Forms","What is VA Form 26-0592?","Counseling checklist for military homebuyers—required for active-duty borrowers.","26-7 Ch.5"),
VQ("Forms","What is VA Form 26-8937?","Verification of VA Benefits—used to confirm disability compensation/funding-fee exemption when the COE doesn't show it.","26-7 Ch.8 §8"),
VQ("Forms","What is VA Form 26-1820?","Report and Certification of Loan Disbursement—closing certification including occupancy.","26-7 Ch.5"),
VQ("Forms","What is VA Form 26-8923?","IRRRL Worksheet—computes the maximum IRRRL loan amount.","26-7 Ch.6"),
VQ("Forms","What is VA Form 26-6381?","Application for Assumption Approval and Release from Personal Liability.","26-7 Ch.5"),
VQ("Forms","What is VA Form 26-1817?","Request for Determination of Loan Guaranty Eligibility—Unmarried Surviving Spouses.","26-7 Ch.2 §4"),
VQ("Forms","What is the Nearest Living Relative statement?","A VA requirement to list a relative's contact info in case the lender cannot reach the borrower.","26-7 Ch.5"),
VQ("Forms","What is a statement of service?","A letter on letterhead from the command/personnel office confirming full name, SSN, DOB, entry date, lost time, expected separation, and character of service—used for the COE while on active duty.","26-7 Ch.2 §3"),
// ---------- Post-closing / wealth ----------
VQ("After closing","When can I refinance?","IRRRL/cash-out after 210 days from the first payment and 6 payments; conventional refinances per lender.","38 U.S.C. §3709"),
VQ("After closing","Can I get a HELOC behind my VA loan?","Yes, from any lender; VA has no restriction on junior liens after closing.","Lender policy"),
VQ("After closing","Can I buy an investment property with a VA loan later?","Not directly, but a former primary residence can become a rental; new purchases must be primary residences.","26-7 Ch.3 §5"),
VQ("After closing","How do I use my home equity to build wealth as a veteran?","Keep the low VA rate, use HELOCs for value-add moves, house-hack 2–4 units, PCS-rent strategy with second-tier entitlement, and IRRRL when rates fall; see the Wealth & Debt page strategies.","Dashboard Wealth strategies"),
VQ("After closing","What is the VA 'home retention' hotline?","877-827-3702—VA loan technicians help borrowers in trouble.","va.gov"),
VQ("After closing","Can I sell before 1 year?","Yes; VA has no resale restriction, though occupancy intent must have been genuine.","26-7 Ch.3 §5"),
VQ("After closing","Does paying off early hurt me?","No prepayment penalty; interest is simple, so extra principal saves interest.","38 CFR 36.4310"),
VQ("After closing","How do I get my entitlement back after selling?","Lender or you submit 26-1880 with the payoff/closing statement; VA restores.","26-7 Ch.2 §9"),
// ---------- Agent/Realtor questions ----------
VQ("Agents","As a listing agent, why should I accept a VA offer?","Fully underwritten VA buyers have the lowest fallout among government programs, the government guaranty supports lender flexibility, VA appraisals use the same comps, and seller-paid costs are negotiable like any loan.","VA fact sheet"),
VQ("Agents","What should agents know about VA appraisals?","Order early (lender does via WebLGY), provide comps, fix MPR items before inspection, know Tidewater's 2-day window and the ROV path; don't contact the appraiser directly.","26-7 Ch.10; Ch.13"),
VQ("Agents","Can a VA buyer waive the termite inspection?","No where VA requires it (CA, NV, AZ, FL, parts of IL); the veteran may pay since 2022.","Circular 26-22-10"),
VQ("Agents","What is the MRP designation?","Military Relocation Professional—NAR certification for agents serving service members; useful for understanding VA loans and PCS timelines.","NAR"),
VQ("Agents","How do I write the seller-credit addendum correctly for VA?","Two lines: (1) seller concessions up to 4% of value (funding fee, prepaids, debt payoff, buydown), (2) seller to pay buyer's allowable closing costs and discount points (no cap).","26-7 Ch.8 §5"),
VQ("Agents","Can the seller pay the VA buyer's non-allowable fees?","Yes; they are typically assigned to the seller or absorbed by the lender.","26-7 Ch.8 §3"),
// ---------- Technology / portals ----------
VQ("Systems","What is WebLGY?","VA's Loan Guaranty web portal lenders use for COEs, appraisal requests, case management and guaranty issuance.","26-7 Ch.1"),
VQ("Systems","Can I get my COE on va.gov?","Yes—sign in to va.gov (ID.me/Login.gov) and request your COE; it may be instant if VA has your service records.","va.gov/housing-assistance/home-loans"),
VQ("Systems","What is CAIVRS?","Credit Alert Verification Reporting System—federal database of defaulted federal debts; lenders must check it for all government loans.","26-7 Ch.4 §7.h"),
VQ("Systems","What is LAPP?","Lender Appraisal Processing Program—allows approved lenders' SARs to review appraisals and issue the NOV without VA staff review.","26-7 Ch.13"),
VQ("Systems","What is the VA funding fee payment system (FFPS)?","The portal lenders use to remit funding fees to VA within 15 days of closing.","26-7 Ch.8 §8"),
// ---------- Special scenarios ----------
VQ("Special","Can I buy a home with a VA loan and have my parents live with me?","Yes; you must occupy; family members can live there.","26-7 Ch.3 §5"),
VQ("Special","Can I buy a bigger home and rent out my current VA-financed home?","Yes with second-tier entitlement and rental offset; lenders may require a lease and deposit proof.","26-7 Ch.3 §4"),
VQ("Special","Can I use VA for a home in a rural area with a well and septic?","Yes with potable water tests and functioning septic; distances per local health authority.","26-7 Ch.12 §6"),
VQ("Special","Can I buy a historic home?","Yes if MPRs are met; lead paint and knob-and-tube wiring issues must be addressed.","26-7 Ch.12"),
VQ("Special","Can I buy a barndominium or unusual property?","If comparable sales support value and MPRs are met; appraisers may struggle with comps in some markets.","26-7 Ch.11"),
VQ("Special","Can I buy a home that was a grow house or had meth contamination?","Only after remediation certified by the appropriate authority; health hazards fail MPRs.","26-7 Ch.12"),
VQ("Special","Can I buy a home on a private road?","Yes with a recorded easement/road maintenance agreement or all-weather access acceptable to the lender.","26-7 Ch.12 §5"),
VQ("Special","Does VA allow leasehold properties (e.g., Hawaii, tribal land)?","Yes if the lease term exceeds the loan term by a required margin and VA approves the lease (NADL for tribal trust land).","26-7 Ch.9 §3"),
VQ("Special","Can I use VA for a tiny home or RV?","No—must be real property on a permanent foundation meeting MPRs.","26-7 Ch.12"),
VQ("Special","Can I buy a home with a pending HOA special assessment?","Yes; the assessment is counted in the housing expense or paid at closing; HOA financial health is reviewed for condos.","26-7 Ch.16"),
VQ("Special","Can I buy a home with a tenant who refuses to leave?","Closing requires occupancy within 60 days (or justification); legal eviction timelines may make the property unsuitable for VA until vacant.","26-7 Ch.3 §5"),
VQ("Special","Can I buy a home from my landlord?","Yes; normal appraisal and underwriting; no identity-of-interest restriction on VA.","26-7 Ch.9"),
VQ("Special","Can an incarcerated veteran's spouse use the benefit?","Spouse occupancy satisfies the requirement if the veteran is on the loan and otherwise eligible; case-by-case.","26-7 Ch.3 §5"),
);
VA_QA.push(
// ---------- Deeper credit & income edge cases ----------
VQ("Credit","What housing payment history does VA want?","Twelve months of on-time rent or mortgage payments is the strongest factor; VA treats a satisfactory housing history as evidence of ability to pay. Living rent-free with family is acceptable with a letter.","26-7 Ch.4 §7"),
VQ("Credit","Do collections have to be paid for VA?","No. VA does not require payment of collections, but lenders may require explanation and may count a payment if a plan exists; judgments differ.","26-7 Ch.4 §7"),
VQ("Credit","Does a charge-off count in DTI?","No payment is counted on a charged-off account; the underwriter weighs it as derogatory history.","26-7 Ch.4 §5"),
VQ("Credit","How does VA treat a repossession?","As a derogatory event explained by LOE; deficiency balances may be collections; no fixed waiting period, judgment call.","26-7 Ch.4 §7"),
VQ("Credit","Are inquiries a problem?","No, but the lender must confirm whether new debt resulted from each recent inquiry (LOE).","26-7 Ch.4 §5"),
VQ("Credit","Do I have to close accounts after paying them off?","No; VA has no such requirement, and closing old accounts can lower scores.","FICO scoring"),
VQ("Credit","Can I get a VA loan with a 580 score?","Yes with a lender whose floor is 580 or lower and a file that shows 12 months clean housing history and solid residual.","26-7 Ch.4 §7; lender matrices"),
VQ("Credit","What if my score dropped during the process?","The lender may re-price or re-underwrite if a new report is pulled; avoid new credit and large balance changes until funding.","Lender policy"),
VQ("Income & residual","How is commission income treated?","2-year average with tax returns; declining trend uses the lower figure; unreimbursed business expenses are deducted.","26-7 Ch.4 §2"),
VQ("Income & residual","Can I use income from a second job?","Yes with a 12–24 month history and likelihood of continuance.","26-7 Ch.4 §2"),
VQ("Income & residual","Does Social Security count?","Yes; grossed up if non-taxable; award letter and continuance (3 years) required.","26-7 Ch.4 §2"),
VQ("Income & residual","Does GI Bill housing allowance (MHA) count as income?","Generally no—it's an education benefit with a limited duration, not stable income; some lenders allow it with continuance documentation, most do not.","26-7 Ch.4 §2 (stability requirement)"),
VQ("Income & residual","Does my pension from the military count?","Yes—retired pay counts in full; the portion waived for VA disability is counted as disability (grossed up).","26-7 Ch.4 §2"),
VQ("Income & residual","Can I count foster care payments?","Yes if there is a history and continuance; non-taxable gross-up may apply.","26-7 Ch.4 §2"),
VQ("Income & residual","Does VA count income from a job I've had for 3 months?","If it's in the same line of work or you have related training, yes; otherwise lenders may need 12 months.","26-7 Ch.4 §2"),
VQ("Income & residual","Is there a minimum residual income for loans under $80,000?","Yes—lower tables apply (e.g., West: $382/664/798/902/935 for 1–5).","26-7 Ch.4 §9"),
VQ("Income & residual","Can child-care costs be ignored in residual?","Childcare expenses are not a line item in residual; however, VA lists 'tax credits for childcare' as a compensating factor.","26-7 Ch.4 §10"),
VQ("Income & residual","Does a car allowance count?","If documented for 2 years and the car payment is deducted, net allowance can be considered.","26-7 Ch.4 §2"),
VQ("Income & residual","How are taxes estimated for residual?","Lenders use federal and state withholding tables and the borrower's actual deductions (pay stubs/LES); non-taxable income has no tax deducted.","26-7 Ch.4 §9"),
VQ("Income & residual","What is payment shock and does VA care?","The increase from current housing cost to the new PITI; large increases are weighed against residual and reserves as a risk factor.","26-7 Ch.4 §10"),
// ---------- Appraisal specifics ----------
VQ("Property","Who picks the VA appraiser?","VA assigns appraisers on a rotating basis through WebLGY; neither the lender nor the agent chooses.","26-7 Ch.10 §2"),
VQ("Property","What does a VA appraisal cost?","VA sets maximum fees by state—typically $600–$1,100 for a single-family home in 2025–2026, more for multi-units and rural areas.","VA appraisal fee schedule by RLC"),
VQ("Property","Can the veteran pay for the appraisal?","Yes; the appraisal fee is an allowable charge.","26-7 Ch.8 §2"),
VQ("Property","Can I talk to the appraiser?","No—communication goes through the lender (SAR). Agents may provide access and a comp package at the appointment without pressuring value.","26-7 Ch.10"),
VQ("Property","What if the appraiser requires a roof inspection?","A licensed roofer's report is obtained; repairs or escrow if needed.","26-7 Ch.12"),
VQ("Property","Can an appraisal be used for a different lender's loan?","Yes within validity; the appraisal is tied to the case number and can be transferred via WebLGY.","26-7 Ch.10"),
VQ("Property","Does VA accept desktop or hybrid appraisals?","VA piloted desktop/exterior-only appraisals for some loan types (2023+ ACE-style pilots); most purchases use full interior appraisals.","Circular 26-22-08 (pilot)"),
VQ("Property","What is a 'subject to' appraisal?","A value conditioned on repairs being completed; a final inspection (VA Form 26-1839/1004D) confirms before closing or funds are escrowed.","26-7 Ch.12"),
VQ("Property","What is an escrow holdback and how much?","Funds (often 1.5× the repair estimate) held at closing for weather-delayed or minor repairs, released after inspection; lender approval required.","26-7 Ch.9 §8"),
VQ("Property","Does VA require GFCI outlets or smoke detectors?","Not as MPRs specifically; safety hazards must be addressed; local code at time of construction governs. Smoke/CO detectors may be required by state law.","26-7 Ch.12"),
VQ("Property","Will cosmetic issues fail the appraisal?","No—cosmetic items (worn carpet, paint in post-1978 homes) don't fail MPRs; safety and soundness do.","26-7 Ch.12"),
VQ("Property","Does VA require a crawl space inspection?","The appraiser must be able to observe the crawl space; standing water, damage or no access can be conditions.","26-7 Ch.12 §2"),
VQ("Property","What about asbestos or radon?","Not MPR items unless damaged/friable; buyers may test. Lead-based paint rules apply to pre-1978 homes (no peeling paint).","26-7 Ch.12"),
VQ("Property","Can I buy a home with a detached ADU and rent it?","Yes if the ADU is legal; rental income may be counted with documentation (lender-dependent).","26-7 Ch.4 §2.n"),
VQ("Property","Does VA appraisal include a cost-to-cure?","Appraisers list required repairs; cost estimates come from contractors.","26-7 Ch.12"),
// ---------- Second liens & seller financing ----------
VQ("Secondary financing","Can I have a second mortgage at closing?","Yes under VA's secondary borrowing rules: combined loans ≤ VA value, borrower qualifies with both, second has reasonable terms and no balloon before 5 years, and the second cannot be used for cash back.","26-7 Ch.9 §4"),
VQ("Secondary financing","Can DPA be a second lien on a VA loan?","Yes, if it meets VA's secondary borrowing criteria (government/nonprofit seconds typically do).","26-7 Ch.9 §4"),
VQ("Secondary financing","Can I use a HELOC on another property for the down/gap?","Yes; the HELOC payment counts in DTI; funds are sourced.","26-7 Ch.4 §8"),
// ---------- Rates & locks ----------
VQ("Pricing","Are VA rates negotiable?","Yes—rates and lender credits/points vary by lender; shop with Loan Estimates on the same day.","Reg Z; market"),
VQ("Pricing","What is par rate?","The rate with no points and no lender credit; buying down costs points, taking a higher rate earns credits.","Market practice"),
VQ("Pricing","How long should my lock be?","Through the closing date plus a buffer (7–10 days); extensions cost money.","Lender policy"),
VQ("Pricing","Can I float down if rates drop?","Some lenders offer a one-time float-down for a fee or at renegotiation thresholds.","Lender policy"),
VQ("Pricing","Does VA have a maximum interest rate?","No; VA removed rate caps in 1992—rates are negotiated between borrower and lender.","38 U.S.C. §3703(c)"),
VQ("Pricing","Are VA ARMs a good idea?","For short holding periods (PCS cycles) a VA 5/1 ARM with 1/1/5 caps can lower cost; assumability adds resale appeal.","38 CFR 36.4312(d)"),
// ---------- Closing day ----------
VQ("Closing day","What happens at a VA closing?","You sign the note, deed of trust, VA forms (26-1820 occupancy/disbursement, 26-0286), the Closing Disclosure and escrow instructions; funds are wired; recording follows (dry states fund after recording).","26-7 Ch.5; TRID"),
VQ("Closing day","When is my first payment due?","The first of the month after a full month passes; e.g., close March 15 → first payment May 1.","Lender practice"),
VQ("Closing day","Can I close on a Friday?","Yes, though funding in dry states may wait until Monday recording; purchases have no rescission period.","State practice"),
VQ("Closing day","Is there a 3-day right to cancel?","Only on refinances of a primary residence (rescission); not on purchases.","Reg Z 1026.23"),
VQ("Closing day","Why must I verify wire instructions by phone?","Wire fraud is common; call escrow at a known number before sending funds; never trust emailed changes.","FBI IC3 guidance"),
VQ("Closing day","Do I need to bring cash to close with $0 down?","Possibly for prepaids/closing costs not covered by credits; the CD shows the exact amount.","TRID"),
// ---------- Entitlement math and edge cases ----------
VQ("Entitlement","Can I use remaining entitlement if my prior loan was assumed by a non-veteran?","Yes, remaining entitlement is usable; the portion tied to the assumed loan stays encumbered until it is paid off.","26-7 Ch.2 §9"),
VQ("Entitlement","Does an IRRRL use additional entitlement?","No; the IRRRL replaces the existing loan and uses the same entitlement.","26-7 Ch.6"),
VQ("Entitlement","How does a cash-out refi affect entitlement?","The new loan amount determines the entitlement charged (25% of the loan); increases may use more entitlement.","26-7 Ch.3 §4"),
VQ("Entitlement","Does county matter for a second-tier loan?","Yes—the new property's county limit sets the maximum guaranty for the remaining-entitlement calculation.","26-7 Ch.3 §4"),
VQ("Entitlement","If my first VA loan used $36,000 in 1995, how much do I have now?","Entitlement charged is 25% of that original loan amount (capped by rules of that era); the lender computes remaining against the current county limit—often substantial.","26-7 Ch.3 §4"),
// ---------- Government/comparative programs ----------
VQ("Other benefits","What is the Native American Direct Loan (NADL)?","A VA direct loan for Native American veterans buying/building on federal trust land with a tribal MOU; low fixed rate, no down payment, 1.25% fee.","38 U.S.C. §3762"),
VQ("Other benefits","Can I combine VA with a down payment assistance grant?","Yes for closing costs; VA has no down payment, so DPA covers costs or prepaids.","26-7 Ch.9"),
VQ("Other benefits","Does VA have a renovation loan?","Not a standalone VA product; lenders offer VA Alteration & Repair loans within VA rules.","Circular 26-18-6"),
VQ("Other benefits","Does VA have an energy efficient mortgage?","Yes—up to $6,000 can be added for energy-efficiency improvements (more with documentation).","26-7 Ch.7 §3"),
VQ("Other benefits","Can I use VA to buy a farm?","Only if the home is the primary purpose and the land value is residential in character; income-producing farms are not eligible.","26-7 Ch.3 §1"),
// ---------- More on process pain points ----------
VQ("Process","My COE lists a name different from my ID (name change). What now?","Provide the legal name-change document; the lender updates WebLGY/VA records.","26-7 Ch.2 §3"),
VQ("Process","My DD-214 is lost. How do I get a copy?","Request from the National Archives (NPRC) via eVetRecs/SF-180; expedited for home loans is sometimes possible; the lender may use VA's records if available.","archives.gov"),
VQ("Process","Can I buy a home with my VA loan while in a bankruptcy repayment plan?","Chapter 13 after 12 months of payments with trustee approval.","26-7 Ch.4 §7.e"),
VQ("Process","Why does the lender need my spouse's credit report in California?","Community-property law: a non-borrowing spouse's debts count in the veteran's DTI; their credit score does not.","26-7 Ch.4 §5"),
VQ("Process","Can the lender charge me for the termite inspection?","Since 2022 the veteran may pay for the WDI inspection in any state.","Circular 26-22-10"),
VQ("Process","Do I need flood insurance if the home is in zone X?","No; only Special Flood Hazard Areas (A/V zones) require it.","26-7 Ch.9 §6"),
VQ("Process","What if the seller won't sign the VA escape clause?","The loan cannot close without it; it protects the veteran and is required by regulation.","38 CFR 36.4303(k)"),
VQ("Process","Can I use a VA loan on a 'for sale by owner' purchase?","Yes; the process is identical; use a title/escrow company.","26-7"),
VQ("Process","Can I buy with VA while owing child support arrears?","Arrears in a payment plan are debts; a judgment or lien must be addressed; CAIVRS may show federal offsets.","26-7 Ch.4 §5"),
VQ("Process","What is the VA 'intent to occupy' certification?","You certify on the application and at closing (26-1820) that you'll occupy within the required period; false certification is fraud.","26-7 Ch.3 §5"),
VQ("Process","How do I check my VA loan status with VA?","VA doesn't track lender processing; ask the lender. After closing, VA's eBenefits shows the loan on your record.","—"),
VQ("Process","Why is my lender asking for a 'statement of service' when I have a COE?","To verify current income continuance and discharge status for active-duty borrowers—separate from eligibility.","26-7 Ch.4 §2.e"),
VQ("Process","Can I get a VA loan with a job offer but no start date?","Generally no; lenders need a start date within a short window and often a first pay stub.","26-7 Ch.4 §2"),
VQ("Process","Can I buy with VA if I have a pending lawsuit?","Disclose it; the underwriter assesses potential liabilities; it is not disqualifying by itself.","26-7 Ch.4"),
VQ("Process","Does VA allow 'as-is' sales?","Yes, but MPRs still apply; 'as-is' refers to seller repairs, not VA requirements.","26-7 Ch.12"),
VQ("Process","Can a VA loan be used for a home being sold at a loss (short sale)?","Yes; the short-sale lender's approval timeline is the main delay.","26-7"),
VQ("Process","Can I include closing costs in the loan amount?","Only the funding fee and energy-efficiency improvements; other costs must be paid by credits or cash.","26-7 Ch.8"),
// ---------- State-specific nuances ----------
VQ("State programs","California: Does VA allow Mello-Roos and HOA together in qualifying?","Yes, both are included in the housing expense; high CFD rates in Temecula/Murrieta newer communities materially affect DTI.","26-7 Ch.4 §5; CA CFD law"),
VQ("State programs","California: Is a termite report required?","Yes—California is on VA's WDI-required list; the veteran may now pay.","Circular 26-22-10"),
VQ("State programs","Nevada: Any special VA considerations?","No state termite requirement exceptions (NV requires WDI per VA list); property-tax exemptions for disabled veterans; Home Is Possible for Heroes pairs with VA.","VA WDI list; NRS 361.091"),
VQ("State programs","Arizona: Are HOA/CFD taxes common?","Some communities carry special districts; disclose and include; AZ requires WDI per VA list.","VA WDI list"),
VQ("State programs","Illinois: Are VA buyers common in the Chicago market?","Yes near Great Lakes and Scott AFB; Illinois is wet-funding; WDI requirements apply in parts; IHDA DPA pairs with VA.","VA WDI list; IHDA"),
VQ("State programs","Florida: What about hurricane/wind and flood?","Wind coverage and flood (SFHA) are often required and expensive—quote early; Florida is a VA WDI state; Hometown Heroes/Salute Our Soldiers layer with VA.","Florida Housing; VA WDI list"),
VQ("State programs","Is CalVet a VA loan?","CalVet is a state program; most CalVet loans carry a VA guaranty (so the funding fee applies) but CalVet is the lender and holds title in a contract of sale until paid.","CalVet program guide"),
// ---------- Counseling, education, scams ----------
VQ("Safety","Are 'VA loan refinance' letters in the mail legitimate?","Often marketing, sometimes misleading. VA never sends unsolicited refinance offers; verify the lender's NMLS and compare the net tangible benefit before responding.","CFPB consumer advisories"),
VQ("Safety","Is there a fee to get a COE or apply for VA benefits?","No. Anyone charging for a COE or 'VA loan application assistance' is unnecessary; the COE is free via lender or va.gov.","va.gov"),
VQ("Safety","Can I be charged for 'VA loan counseling'?","Not by the lender; VA homebuyer counseling is free; HUD-approved counselors charge nominal fees for other programs.","26-7 Ch.8"),
VQ("Safety","How do I avoid churning on IRRRLs?","Apply the recoupment and NTB tests honestly; refinance only when savings justify costs; VA's 36-month rule exists for this reason.","38 U.S.C. §3709"),
VQ("Safety","What is the VA home loan 'Welcome Home' program?","Not a VA program—marketing names vary; ask for the actual program terms.","—"),
// ---------- Numbers quick refs ----------
VQ("Quick reference","2026 conforming limit used for VA partial-entitlement math?","$832,750 baseline 1-unit; high-cost counties up to $1,249,125 (e.g., LA/Orange); San Diego $1,077,550 (verify FHFA table).","FHFA 2026 limits"),
VQ("Quick reference","Funding fee table (2026).","Purchase/construction/cash-out: first use 2.15% (<5% down), 1.5% (5–9.99%), 1.25% (≥10%); subsequent 3.3%/1.5%/1.25%. IRRRL 0.5%. Assumption 0.5%. Manufactured (chattel) 1%. NADL 1.25%.","38 U.S.C. §3729; Circular 26-23-06"),
VQ("Quick reference","Residual income table (loans ≥ $80,001).","Northeast 450/755/909/1,025/1,062; Midwest 441/738/889/1,003/1,039; South 441/738/889/1,003/1,039; West 491/823/990/1,117/1,158; +$80 per additional member up to 7.","26-7 Ch.4 §9"),
VQ("Quick reference","Which states require a termite (WDI) inspection?","Most of the South and West; CA, NV, AZ, FL yes; IL partially (per county). VA publishes the list.","VA WDI requirement list"),
VQ("Quick reference","VA occupancy deadline.","60 days after closing, extendable to 12 months with lender-accepted justification.","26-7 Ch.3 §5"),
VQ("Quick reference","IRRRL and cash-out seasoning.","210 days from first payment due date AND 6 monthly payments.","38 U.S.C. §3709(c)"),
VQ("Quick reference","Seller concession cap.","4% of reasonable value for concessions; closing costs and points unlimited.","26-7 Ch.8 §5"),
VQ("Quick reference","Lender origination cap.","1% flat or itemized ≤1%.","26-7 Ch.8 §2"),
VQ("Quick reference","Guaranty amount.","25% of the loan with full entitlement; 25% × county limit minus used entitlement with partial.","38 U.S.C. §3703"),
VQ("Quick reference","Max IRRRL term.","Original term + 10 years, not to exceed 30 years.","26-7 Ch.6"),
VQ("Quick reference","VA ARM caps.","1/1/5 for 3/1 and 5/1 hybrids; 2/2/6 for 7/1 and 10/1 (verify lender).","38 CFR 36.4312"),
VQ("Quick reference","VA loan technician hotline.","877-827-3702 (home retention / general loan questions).","va.gov"),
// ---------- ISA/agent scripting Q&A ----------
VQ("Client questions","How much house can I afford with a VA loan?","Driven by residual income and DTI rather than a down payment; a quick rule: PITI ≈ 35–41% of gross income with residual satisfied; run the Affordability calculator with your family size and region.","26-7 Ch.4 §9–10"),
VQ("Client questions","What's the monthly payment on $500k at today's rate?","Depends on the rate; at 6.25% P&I ≈ $3,078 on $500,000 (plus taxes/insurance/HOA; funding fee if financed adds ~$66). Use the calculator for a disclosed estimate.","Calculator"),
VQ("Client questions","How fast can I get pre-approved?","Same day with LES/pay stubs, bank statements and a credit pull; a fully underwritten TBD approval in 24–48 hours.","Process"),
VQ("Client questions","Should I wait for rates to drop?","You can refinance later with an IRRRL (no appraisal/income); waiting often costs more in price appreciation and rent than the rate difference.","38 U.S.C. §3709"),
VQ("Client questions","Can I buy if I just PCS'd and my spouse hasn't found work yet?","Yes if your income alone qualifies; the spouse's future income isn't needed.","26-7 Ch.4"),
VQ("Client questions","What if I'm about to deploy for 9 months?","Buy before you leave with a POA for your spouse, or after return; occupancy can be satisfied by the spouse.","26-7 Ch.3 §5; Ch.9 §7"),
VQ("Client questions","Will using VA affect my other VA benefits?","No. Home loan use does not affect disability, education, or healthcare benefits.","va.gov"),
VQ("Client questions","Can I use VA to buy a condo near base to rent later when I PCS?","Yes—buy as primary, occupy, then rent after PCS; buy the next home with second-tier entitlement.","26-7 Ch.3"),
VQ("Client questions","How do I know if a condo is VA-approved before I offer?","Ask your lender to search WebLGY; approvals take weeks, so check before writing.","26-7 Ch.16"),
VQ("Client questions","What do I need to bring to our first meeting?","DD-214 or statement of service, two LES/pay stubs, two months bank statements, ID, and a list of debts and dependents (for residual).","26-7 Ch.4"),
);
VA_QA.push(
VQ("Eligibility","Does a 'uncharacterized' or entry-level separation qualify?","Usually not—uncharacterized separations under 180 days generally don't meet minimum service unless due to a service-connected disability; VA may make a determination.","26-7 Ch.2 §1"),
VQ("Eligibility","Can a veteran living abroad get a VA loan for a U.S. home?","Yes, if occupancy within the required period is credible (e.g., returning); the home must be in the U.S.","26-7 Ch.3 §5"),
VQ("Credit","Is a 'thin file' with one credit card enough?","With 12 months of rent and utility history added as alternative credit, often yes on a manual underwrite.","26-7 Ch.4 §7.c"),
VQ("Income & residual","Can I count BAH if I'm about to lose it at ETS?","Only if continuance is shown (re-enlistment) or replaced by documented civilian income/pension.","26-7 Ch.4 §2.e"),
VQ("Property","Can I buy a home with a wood stove as the only heat?","Heating must be adequate and safe; wood stoves alone may fail MPRs unless typical for the area with a permanent, approved system.","26-7 Ch.12 §2"),
VQ("Refinance","Can an IRRRL include a lender credit to cover all costs?","Yes—'no-cost' IRRRLs use lender credits; the recoupment test is easier with lower costs.","38 U.S.C. §3709"),
VQ("Assumption","Can I assume a VA loan on an investment property?","Assumers generally must occupy for most servicers' approvals; VA rules focus on creditworthiness; check with the servicer.","26-7 Ch.5"),
VQ("Process","What is a 'conditional approval'?","An underwriter's approval subject to listed conditions (documents, appraisal, title) that must be satisfied before clear to close.","Industry practice"),
VQ("Process","What is 'clear to close'?","All conditions satisfied; the lender prepares closing documents and schedules signing.","Industry practice"),
VQ("Closing costs","Are recording fees and transfer taxes allowable?","Recording fees yes; transfer taxes are allowable where customarily paid by the buyer (lender verifies state/local practice).","26-7 Ch.8 §2"),
VQ("After closing","Can I add my spouse to title after closing?","Yes by deed; it doesn't change the loan; some lenders require notice; no due-on-sale trigger for spouses under Garn-St Germain.","12 U.S.C. §1701j-3"),
VQ("After closing","Does VA notify me if my servicer changes?","The old and new servicers send transfer notices (goodbye/hello letters) 15 days before/after; VA doesn't.","RESPA §6"),
VQ("Quick reference","Which VA forms are signed at closing?","26-1820 (Report and Certification of Loan Disbursement), 26-0286 (Loan Summary), occupancy certification, and for IRRRLs 26-8923; plus standard note/deed/CD.","26-7 Ch.5"),
VQ("Client questions","Can I buy a home for my adult child who is a veteran using my money?","The veteran must be the borrower and occupant; parents can gift funds for costs.","26-7 Ch.3 §5; Ch.4 §8"),
);
const VA_QA_TAB={html:()=>`<div class="card"><h3>VA loan Q&A library <span class="sub">${VA_QA.length} questions · in-depth answers with references (VA Pamphlet 26-7, 38 U.S.C./CFR, circulars) · verify dated figures</span></h3><div class="row"><input type="text" id="qa_q" placeholder="Search questions and answers…" style="max-width:320px">${sel("qa_c","Category",[["","All categories"],...[...new Set(VA_QA.map(q=>q.cat))].map(c=>[c,c])],"")}<span class="sp"></span><button class="btn ghost sm" id="qa_docx">⬇ All Q&A (Word)</button><button class="btn ghost sm" id="qa_coach">Ask the Coach</button></div><div id="qa_cnt" class="mut sm" style="margin-top:6px"></div><div id="qa_list" style="margin-top:8px"></div></div>`,
 mount(){const draw=()=>{const q=$("#qa_q").value.toLowerCase(),c=$("#qa_c").value;const w=q.split(/\s+/).filter(Boolean);const rows=VA_QA.map((x,i)=>({x,i,s:w.length?w.filter(t=>(x.q+" "+x.a+" "+x.cat).toLowerCase().includes(t)).length:1})).filter(r=>r.s>0&&(!c||r.x.cat===c)).sort((a,b)=>b.s-a.s||a.i-b.i);$("#qa_cnt").textContent=`${rows.length} of ${VA_QA.length}`;$("#qa_list").innerHTML=rows.slice(0,120).map(({x,i})=>`<details class="acc"><summary><b>${esc(x.q)}</b> <span class="tag">${esc(x.cat)}</span></summary><div class="sm" style="padding:6px 0 8px">${esc(x.a)}<div class="mut" style="margin-top:4px">Reference: ${esc(x.ref)}</div><button class="btn ghost sm" data-qc="${i}" style="margin-top:4px">Copy</button></div></details>`).join("")+(rows.length>120?`<p class="mut sm">Showing 120 — refine your search.</p>`:"");$$("[data-qc]").forEach(b=>b.onclick=()=>{const x=VA_QA[b.dataset.qc];copy(`Q: ${x.q}\nA: ${x.a}\nRef: ${x.ref}`)})};
  $("#qa_q").oninput=draw;$("#qa_c").onchange=draw;$("#qa_docx").onclick=()=>saveFile("va-loan-qa-library.docx",docxBytes([{t:"VA Loan Q&A Library",h:1},...[...new Set(VA_QA.map(q=>q.cat))].flatMap(c=>[{t:c,b:1},...VA_QA.filter(q=>q.cat===c).flatMap(q=>[{t:"Q: "+q.q,b:1},{t:q.a},{t:"Reference: "+q.ref}])])]));$("#qa_coach").onclick=()=>{const q=$("#qa_q").value.trim();if(q)store.set("coachHist",[...store.get("coachHist",[]),q]);location.hash="coach"};draw()}};
